const app=document.querySelector('#app');let data=null,view='Home',user=null,memoryAlbums=[],memoryAlbumFilter='all',chatTheme='dark',memorySortAlbum=null,memoryTouchHold=null,memoryTouchDrag=null,memorySuppressClick=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'৳'+Number(n||0).toLocaleString('en-BD',{maximumFractionDigits:0});const date=s=>s?new Date(s).toLocaleDateString('en-BD',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Dhaka'}):'Date not set';const localDhaka=s=>{if(!s)return '';const d=new Date(s);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d).replace(' ','T')};const initials=n=>(n||'?').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase();async function api(url,opts={}){const r=await fetch('/api'+url,{...opts,headers:{...(opts.body&&!(opts.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...(opts.headers||{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'Something went wrong');return d}function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.classList.add('toast');setTimeout(()=>e.classList.remove('toast'),2800)}function btn(label,action,cls='btn'){const match=action.match(/^([\w$]+)\((.*)\)$/s);let args=[];if(match&&match[2].trim()){let part='',quote='',depth=0,escape=false;for(const ch of match[2]){if(escape){part+=ch;escape=false;continue}if(ch==='\\'&&quote){part+=ch;escape=true;continue}if(quote){part+=ch;if(ch===quote)quote='';continue}if(ch==='\''||ch==='"'){quote=ch;part+=ch;continue}if(ch==='('){depth++;part+=ch;continue}if(ch===')'){depth--;part+=ch;continue}if(ch===','&&depth===0){args.push(parseActionArg(part));part='';continue}part+=ch}args.push(parseActionArg(part))}return `<button class="${esc(cls)}" data-action="${match?esc(match[1]):''}" data-args="${esc(JSON.stringify(args))}">${esc(label)}</button>`}function parseActionArg(v){v=v.trim();if((v.startsWith("'")&&v.endsWith("'"))||(v.startsWith('"')&&v.endsWith('"')))return v.slice(1,-1).replaceAll("\\'","'").replaceAll('\\"','"').replaceAll('\\\\','\\');if(v==='null')return null;if(v==='true')return true;if(v==='false')return false;if(v!==''&&!Number.isNaN(Number(v)))return Number(v);return null}function go(v){if(v!=='Locations'&&typeof stopLocationWatch==='function')stopLocationWatch();if(v!=='Chat'){clearInterval(window.chatTimer);window.chatSource?.close();window.chatSource=null}view=v;render()}function statusClass(s){return ({Upcoming:'upcoming',Completed:'complete',Cancelled:'cancelled',Ongoing:'upcoming'})[s]||''}async function boot(){try{const st=await api('/status');const me=await api('/me');user=me.user;if(st.setup&&!user){setupScreen();return}if(!user){loginScreen();return}data=await api('/dashboard');render()}catch(e){app.innerHTML=`<div class="login"><h1>Unable to connect to the server</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="boot" data-args="[]">Try again</button></div>`}}function setupScreen(){app.innerHTML=`<main class="auth-layout">${carouselMarkup()}<div class="login"><div class="brand-mark">✦</div><h1 style="margin-top:20px">Create your first admin account</h1><p>This is a one-time step. Your private friends space is not set up yet.</p><form class="form" data-submit="submitSetup"><div class="field"><label>Your name</label><input name="name" required></div><div class="field"><label>Username</label><input name="username" minlength="3" maxlength="32" required></div><div class="field"><label>Password — at least 10 characters</label><input name="password" type="password" minlength="10" required></div><button class="btn primary">Create admin account</button></form><p class="muted">Before deployment, change SESSION_SECRET in your .env file.</p></div></main>`;initCarousel()}async function submitSetup(e){e.preventDefault();try{await api('/setup',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Admin account created');boot()}catch(x){toast(x.message)}}function loginScreen(){app.innerHTML=`<main class="auth-layout">${carouselMarkup()}<div class="login"><div class="brand-mark">✦</div><h1 style="margin-top:20px">Welcome back</h1><p>Sign in to your private friends space.</p><form class="form" data-submit="submitLogin"><div class="field"><label>Phone number or admin username</label><input name="username" autocomplete="username" required></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn primary">Sign in</button></form><p class="muted">New to the group? <button class="btn ghost" data-action="registerScreen" data-args="[]">Create a member account</button></p></div></main>`;initCarousel()}
function registerScreen(){app.innerHTML=`<main class="auth-layout">${carouselMarkup()}<div class="login"><div class="brand-mark">✦</div><h1 style="margin-top:20px">Join the group</h1><p>Register with your name, phone number, and password to enter the group.</p><form class="form" data-submit="submitRegister"><div class="field"><label>Your name</label><input name="name" minlength="2" maxlength="100" required></div><div class="field"><label>Phone number</label><input name="phone" type="tel" autocomplete="tel" required></div><div class="field"><label>Password — at least 6 characters</label><input name="password" type="password" minlength="6" autocomplete="new-password" required></div><button class="btn primary">Request member account</button><button type="button" class="btn ghost" data-action="loginScreen" data-args="[]">Back to sign in</button></form></div></main>`;initCarousel()}
async function submitRegister(e){e.preventDefault();try{await api('/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Account created');await boot()}catch(x){toast(x.message)}}async function submitLogin(e){e.preventDefault();try{await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});boot()}catch(x){toast(x.message)}}function initCarousel(){clearTimeout(window.carouselTimer);document.querySelectorAll('.memory-carousel video').forEach(v=>v.pause());const root=document.querySelector('#memoryCarousel');if(!root)return;window.carouselIndex=0;showCarouselSlide(0)}function showCarouselSlide(index){const root=document.querySelector('#memoryCarousel');if(!root)return;const slides=[...root.querySelectorAll('.carousel-slide')];if(!slides.length)return;clearTimeout(window.carouselTimer);root.querySelectorAll('video').forEach(v=>v.pause());window.carouselIndex=((index%slides.length)+slides.length)%slides.length;slides.forEach((s,i)=>{s.classList.toggle('active',i===window.carouselIndex);const d=root.querySelectorAll('.carousel-dot')[i];d?.classList.toggle('active',i===window.carouselIndex)});const count=root.querySelector('#carouselCurrent');if(count)count.textContent=String(window.carouselIndex+1).padStart(2,'0');const slide=slides[window.carouselIndex],video=slide.querySelector('video');if(!video){window.carouselTimer=setTimeout(()=>showCarouselSlide(window.carouselIndex+1),6500);return}video.muted=true;video.currentTime=0;const next=()=>{if(document.querySelector('#memoryCarousel')===root)showCarouselSlide(window.carouselIndex+1)};video.onended=next;video.onerror=()=>{window.carouselTimer=setTimeout(next,6500)};const scheduleVideoEnd=()=>{clearTimeout(window.carouselTimer);window.carouselTimer=setTimeout(next,Math.max(8000,Math.min((video.duration||20)*1000+500,120000)))};window.carouselTimer=setTimeout(next,20000);if(video.readyState>=1)scheduleVideoEnd();else video.onloadedmetadata=scheduleVideoEnd;video.play().catch(()=>{clearTimeout(window.carouselTimer);window.carouselTimer=setTimeout(next,10000)})}function carouselNext(){showCarouselSlide((window.carouselIndex||0)+1)}function carouselPrev(){showCarouselSlide((window.carouselIndex||0)-1)}function carouselSelect(index){showCarouselSlide(Number(index)||0)}function header(){return `<header class="topbar"><div class="brand"><div class="brand-mark">${data.settings.logo?`<img src="${esc(data.settings.logo)}" alt="">`:"✦"}</div><div>${esc(data.group)}<small>Your private home for friendship and travel</small></div></div><nav class="nav">${['Home','Tours','Locations','Memories','Members','Payments'].map(v=>`<button class="${view===v?'active':''}" data-action="go" data-args="[&quot;${v}&quot;]">${({Home:'Home',Tours:'Tours',Memories:'Memories',Members:'Members',Payments:'Payments',Locations:'Locations'})[v]}</button>`).join('')}${user.role==='admin'?`<button class="${view==='Admin'?'active':''}" data-action="go" data-args="[&quot;Admin&quot;]">Admin</button><button class="${view==='Settings'?'active':''}" data-action="go" data-args="[&quot;Settings&quot;]">Settings</button>`:''}</nav><div class="header-actions"><button class="theme-corner-toggle" data-action="toggleTheme" data-args="[]" title="${document.documentElement.dataset.theme==='light'?'Switch to dark theme':'Switch to light theme'}" aria-label="Toggle light or dark theme">${document.documentElement.dataset.theme==='light'?'◐':'☼'}</button><button class="chat-corner-trigger" data-action="toggleChatWidget" data-args="[]" aria-label="Open chat">✉ <span>Chat</span><i id="chatHeaderUnread" hidden></i></button>${btn('Sign out','logout()','btn ghost')}</div></header>`}function tourCards(list){if(!list.length)return `<div class="empty">No tours yet. An admin can add the first one.</div>`;return `<div class="grid">${list.map(t=>`<article class="card tour-card"><div class="tour-art">${t.cover?`<img src="${esc(t.cover)}" alt="">`:''}<span class="badge ${statusClass(t.status)}">${esc(t.status==='Completed'?'COMPLETED ✓':t.status)}</span></div><div class="tour-body"><div class="eyebrow">${esc(t.destination)}</div><h3>${esc(t.title)}</h3><div class="meta">${date(t.start_at)}${t.end_at?' — '+date(t.end_at):''}<br>${t.participants.length} travelers · per person ${money(t.contribution)}${t.distance_km?` · ${esc(t.distance_km)} km`:``}</div>${t.description?`<p class="meta">${esc(t.description)}</p>`:''}${t.lat&&t.lon?`<a class="maplink" target="_blank" rel="noopener" href="https://www.google.com/maps?q=${t.lat},${t.lon}">Google Maps ↗</a>`:''}<div style="margin-top:13px">${t.status==='Upcoming'?`<div class="countdown" data-date="${esc(t.start_at||'')}"></div>`:''}</div><button class="btn" style="margin-top:15px" data-action="tourDetail" data-args="[${t.id}]">Explore tours →</button></div></article>`).join('')}</div>`}function carouselMarkup(){return `<section class="memory-carousel" id="memoryCarousel" aria-label="Friends photo and video slideshow"><div class="carousel-track"><figure class="carousel-slide active" data-index="0"><img src="/media/friends-forever.jpeg" alt="Friends Forever — a hand-drawn beach memory" fetchpriority="high"><figcaption><span>Our friendship</span><b>Friends Forever · Same Vibes, Different Day</b></figcaption></figure><figure class="carousel-slide" data-index="1"><img src="/media/group-on-beach.jpeg" alt="Friends together at the beach" loading="lazy"><figcaption><span>The moments we share</span><b>Our group photo at the beach</b></figcaption></figure><figure class="carousel-slide" data-index="2"><img src="/media/beach-memories.jpeg" alt="Friends making memories by the sea" loading="lazy"><figcaption><span>Travel memories</span><b>Waves, skies, and our friends</b></figcaption></figure><figure class="carousel-slide video-slide" data-index="3"><video muted playsinline preload="metadata" poster="/media/beach-memories.jpeg" aria-label="Muted video of our trip"><source src="/media/group-video.mp4" type="video/mp4"></video><figcaption><span>Our video</span><b>One trip. A thousand stories. <small>· Sound off</small></b></figcaption></figure></div><div class="carousel-shade"></div><div class="carousel-controls"><button class="carousel-arrow" type="button" data-action="carouselPrev" data-args="[]" aria-label="Previous slide">‹</button><div class="carousel-dots" role="group" aria-label="Choose a slide"><button type="button" class="carousel-dot active" data-action="carouselSelect" data-args="[0]" aria-label="Slide 1"></button><button type="button" class="carousel-dot " data-action="carouselSelect" data-args="[1]" aria-label="Slide 2"></button><button type="button" class="carousel-dot " data-action="carouselSelect" data-args="[2]" aria-label="Slide 3"></button><button type="button" class="carousel-dot " data-action="carouselSelect" data-args="[3]" aria-label="Slide 4"></button></div><button class="carousel-arrow" type="button" data-action="carouselNext" data-args="[]" aria-label="Next slide">›</button></div><div class="carousel-count" aria-live="polite"><span id="carouselCurrent">01</span> / 04</div></section>`}function home(){const upcoming=data.tours.filter(t=>t.status==='Upcoming'&&t.start_at).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at))[0],completed=data.tours.filter(t=>t.status==='Completed');return `${carouselMarkup()}<section class="hero"><div class="eyebrow">Friendship, journeys, and stories</div><h1>${esc(data.settings.slogan)}</h1><p>${esc(data.settings.welcome)}</p><div class="hero-actions">${btn('Explore our tours','go(\'Tours\')','btn primary')}${btn('Memory album','go(\'Memories\')')}</div></section><div class="stats"><div class="stat"><label>Group members</label><strong>${data.members.filter(m=>m.active).length}</strong></div><div class="stat"><label>Completed tours</label><strong>${completed.length}</strong></div><div class="stat"><label>Upcoming tours</label><strong>${upcoming?'1':'0'}</strong></div><div class="stat"><label>Contributions collected</label><strong>${money(data.collected)}</strong></div></div>${upcoming?`<div class="section-head"><div><h2>Next destination</h2><p>Countdown to our next trip</p></div></div>${tourCards([upcoming])}`:''}<div class="section-head"><div><h2>Recent adventures</h2><p>Favorite moments from our journeys</p></div>${btn('All tours →','go(\'Tours\')')}</div>${tourCards(completed.slice(0,3))}${data.tours.some(t=>t.gallery.length)?`<div class="section-head"><div><h2>Favorite memories</h2><p>Featured moments from our gallery</p></div>${btn('All memories →','go(\'Memories\')')}</div><div class="gallery featured-gallery">${data.tours.flatMap(t=>t.gallery).slice(0,4).map(p=>mediaCard(p)).join('')}</div>`:''}${data.announcements.length?`<div class="section-head"><div><h2>News & announcements</h2></div></div><div class="grid">${data.announcements.map(a=>`<article class="card"><span class="eyebrow">Announcements</span><h3>${esc(a.title)}</h3><p class="meta">${esc(a.body)}</p></article>`).join('')}</div>`:''}`}function memberCard(m){return `<div class="card member-row"><div class="avatar">${m.photo?`<img src="${esc(m.photo)}" alt="${esc(m.name)}">`:initials(m.name)}</div><div class="grow"><b>${esc(m.name)}</b><div class="muted">${esc(m.nickname||m.bio||'Our friend')}</div></div><button class="btn ghost" data-action="memberDetail" data-args="[${m.id}]">Profile</button>${user.role==='admin'?btn('Edit',`editMember(${m.id})`):''}</div>`}function toursPage(){const list=data.tours;return `<div class="section-head"><div><h2>Our tours</h2><p>Upcoming plans and stories from the road</p></div>${user.role==='admin'?btn('+ New tour','tourForm()','btn primary'):''}</div><div class="filters"><div class="field"><input id="tourSearch" placeholder="Search tours or destinations" data-filter="tours"></div><div class="field"><select id="tourFilter" data-filter="tours"><option value="all">All statuses</option><option>Upcoming</option><option>Ongoing</option><option>Completed</option><option>Cancelled</option></select></div></div><div id="tourResults">${tourGroups(list)}</div>`}function membersPage(){return `<div class="section-head"><div><h2>Our people</h2><p>The friends and family in our group</p></div>${user.role==='admin'?btn('+ Add members','memberForm()','btn primary'):btn('My profile','memberDetail('+user.member_id+')','btn primary')}</div><div class="field" style="max-width:380px;margin-bottom:16px"><input id="memberSearch" placeholder="Search by name…" data-filter="members"></div><div class="grid" id="memberGrid">${data.members.map(memberCard).join('')}</div>`}function filterMembers(){const q=document.querySelector('#memberSearch').value.toLowerCase();document.querySelector('#memberGrid').innerHTML=data.members.filter(m=>m.name.toLowerCase().includes(q)||(m.nickname||'').toLowerCase().includes(q)).map(memberCard).join('')||'<div class="empty">No members found</div>'}function paymentsPage(){const rows=data.tours.flatMap(t=>t.participants.map(p=>({t,p})));return `<div class="section-head"><div><h2>Tour contributions</h2><p>${user.role==='admin'?'Payments, balances, and waivers by member':'Your tours and payments'}</p></div></div>${rows.length?`<div class="field" style="max-width:300px;margin:0 0 14px"><select id="payFilter" data-filter="payments"><option value="all">All payment statuses</option><option value="PENDING">Pending</option><option value="PARTIAL">Partially paid</option><option value="PAID">Paid</option><option value="WAIVED">Waived</option></select></div><div class="card table-wrap"><table class="table"><thead><tr><th>Tours</th><th>Members</th><th>Required</th><th>Paid</th><th>Balance</th><th>Status</th>${user.role==='admin'?'<th>Actions</th>':''}</tr></thead><tbody id="paymentRows">${rows.map(({t,p})=>{const rem=Math.max(0,t.contribution-p.paid),status=p.waived?'WAIVED':p.paid>=t.contribution?'PAID':p.paid?'PARTIAL':'PENDING';return `<tr data-status="${status}"><td>${esc(t.title)}</td><td><span class="avatar small">${p.photo?`<img src="${esc(p.photo)}" alt="">`:initials(p.name)}</span> ${esc(p.name)}</td><td>${money(t.contribution)}</td><td>${money(p.paid)}</td><td>${money(rem)}</td><td><span class="badge ${p.waived||p.paid>=t.contribution?'paid':p.paid?'upcoming':'pending'}">${status}</span></td>${user.role==='admin'?`<td>${!p.waived&&rem>0?btn('+ Paid','paymentForm('+t.id+','+p.id+')'):''} ${!p.waived?btn('Waived','waive('+t.id+','+p.id+')','btn ghost'):''}</td>`:''}</tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${user.role==='admin'?'Add participants to see payments here.':'You have not been added to any tours yet.'}</div>`}<div class="section-head"><div><h2>Receipt history</h2><p>Latest ${data.payments.length}records</p></div></div>${data.payments.length?`<div class="card table-wrap"><table class="table"><thead><tr><th>Receipt</th><th>Date</th><th>Tours</th>${user.role==='admin'?'<th>Members</th>':''}<th>Amount</th><th>Method</th><th></th></tr></thead><tbody>${data.payments.map(p=>`<tr><td>${esc(p.receipt)}</td><td>${date(p.paid_at)}</td><td>${esc(p.tour)}</td>${user.role==='admin'?`<td>${esc(p.member)}</td>`:''}<td>${money(p.amount)}</td><td>${esc(p.method)}</td><td>${btn('Receipt','openReceipt(\''+esc(p.receipt)+'\')')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No payment receipts yet.</div>'}`}function memories(){return `<div class="section-head"><div><h2>Memories & albums</h2><p>Share any moment, create your own albums, and choose who can see them.</p></div><div class="hero-actions"><button class="btn" data-action="newMemoryAlbum">＋ New album</button><button class="btn primary" data-action="photoForm">＋ Upload photos</button></div></div><div class="filters memory-filters"><div class="field"><input id="memorySearch" placeholder="Search photos, captions, albums" data-filter="memories"></div><div class="field"><select id="memoryAlbumFilter" data-filter="memories"><option value="all">All albums</option></select></div></div><div id="memoryAlbumList" class="memory-album-list"></div><div class="section-head memory-results-head"><div><h2>Photos</h2><p id="memoryResultLabel">Loading albums…</p></div></div><p id="memorySortHint" class="memory-sort-hint" hidden>Press and hold a photo, then move it to change the order. On a computer, drag a photo.</p><div class="gallery" id="memoryGrid"><div class="empty">Loading memories…</div></div>`}function adminPage(){const sums=data.tours.flatMap(t=>t.participants.map(p=>({t,p}))),due=sums.reduce((a,x)=>a+(x.p.waived?0:Math.max(0,x.t.contribution-x.p.paid)),0),expenses=data.tours.reduce((n,t)=>n+t.expenses.reduce((a,x)=>a+x.amount,0),0);return `<div class="section-head"><div><h2>Admin dashboard</h2><p>Group activity and finances</p></div><div class="hero-actions">${btn('Export CSV','exportCsv()')}${btn('Download database backup','downloadBackup()')}${btn('Group settings','go(\'Settings\')')}</div></div><div class="stats"><div class="stat"><label>Active Members</label><strong>${data.members.filter(m=>m.active).length}</strong></div><div class="stat"><label>Total / completed tours</label><strong>${data.tours.length} / ${data.tours.filter(t=>t.status==='Completed').length}</strong></div><div class="stat"><label>Total collected</label><strong>${money(data.collected)}</strong></div><div class="stat"><label>Outstanding / expenses</label><strong>${money(due)} / ${money(expenses)}</strong></div></div><div class="section-head"><div><h2>New announcements</h2><p>Visible to signed-in members</p></div></div><div class="card"><form class="form two" data-submit="saveAnnouncement"><div class="field"><label>Title</label><input name="title" required></div><div class="field full"><label>Message</label><textarea name="body" required></textarea></div><button class="btn primary">Publish announcement</button></form>${data.announcements.map(a=>`<div class="activity-row"><div class="grow"><b>${esc(a.title)}</b><div class="muted">${esc(a.body)}</div></div>${btn('Delete','deleteAnnouncement('+a.id+')','btn ghost')}</div>`).join('')}</div><div class="section-head"><div><h2>SMS / notification log</h2><p>SMS is only marked delivered when the provider confirms it.</p></div></div><div class="card">${data.notifications.map(n=>`<div class="activity-row"><b>${esc(n.channel.toUpperCase())}</b><span class="grow">${esc(n.recipient||'No phone number')} · ${esc(n.detail||'')}</span><span class="badge ${n.status==='delivered'?'paid':'pending'}">${esc(n.status)}</span></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</div><div class="section-head"><div><h2>Recent activity</h2></div></div><div class="card">${data.activity.map(a=>`<div class="activity-row"><span class="avatar">✦</span><div class="grow">${esc(a.text)}<div class="muted">${date(a.created_at)}</div></div></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div><div class="section-head"><div><h2>Manage members</h2></div>${btn('+ Add members','memberForm()','btn primary')}</div><div class="card">${data.members.map(m=>`<div class="member-row"><div class="avatar">${m.photo?`<img src="${esc(m.photo)}" alt="">`:initials(m.name)}</div><div class="grow"><b>${esc(m.name)}</b><div class="muted">${esc(m.phone||'No phone added')}${m.active?'':' · Pending approval'}</div></div>${btn('Profile',`memberDetail(${m.id})`)} ${btn('Edit',`editMember(${m.id})`)}</div>`).join('')}</div><div class="section-head"><div><h2>Manage tours</h2></div>${btn('+ New tour','tourForm()','btn primary')}</div>${tourCards(data.tours)}`}function editTour(id){const t=data.tours.find(x=>x.id===id);if(t)tourForm(t)}function tourGroups(list){return ['Upcoming','Ongoing','Completed','Cancelled'].map(st=>{const rows=list.filter(t=>t.status===st);return rows.length?`<div class="section-head"><div><h2>${({Upcoming:'Upcoming',Ongoing:'Ongoing',Completed:'Completed ✓',Cancelled:'Cancelled'})[st]}</h2></div></div>${tourCards(rows)}`:''}).join('')||'<div class="empty">No tours have been added yet.</div>'}function filterTours(){const q=(document.querySelector('#tourSearch')?.value||'').toLowerCase(),st=document.querySelector('#tourFilter')?.value||'all';document.querySelector('#tourResults').innerHTML=tourGroups(data.tours.filter(t=>(st==='all'||t.status===st)&&(t.title+' '+t.destination).toLowerCase().includes(q)))}function editOwnProfile(){const m=data.members.find(x=>x.id===user.member_id);if(!m)return;modal('Edit my profile','You can change your own profile details and photo.',`<form class="form" data-submit="saveOwnProfile"><div class="field"><label>Name</label><input name="name" value="${esc(m.name)}" minlength="2" maxlength="100" required></div><div class="field"><label>Nickname</label><input name="nickname" value="${esc(m.nickname||'')}"></div><div class="field"><label>Phone number</label><input name="phone" type="tel" value="${esc(m.phone||'')}" required></div><div class="field"><label>Short bio</label><textarea name="bio">${esc(m.bio||'')}</textarea></div><div class="field"><label>Profile photo</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><button class="btn primary">Save my profile</button></form>`)}
async function saveOwnProfile(e){e.preventDefault();try{const fd=new FormData(e.target),photo=fd.get('photo'),values=Object.fromEntries(fd);delete values.photo;await api('/me/profile',{method:'PUT',body:JSON.stringify(values)});if(photo?.size){const image=new FormData();image.append('photo',photo);await api('/me/profile/photo',{method:'POST',body:image})}document.querySelector('.overlay')?.remove();await boot();go('Members');memberDetail(user.member_id);toast('Your profile was updated')}catch(x){toast(x.message)}}function memberDetail(id){const m=data.members.find(x=>x.id===id);if(!m)return;const tours=data.tours.filter(t=>t.participants.some(p=>p.id===id)),payments=user.role==='admin'?data.payments.filter(p=>p.member_id===id):data.payments.filter(p=>p.member_id===user.member_id);modal(esc(m.name),esc(m.nickname||'Our friend'),`<div class="profile-actions">${id===user.member_id?btn('Edit my profile','editOwnProfile()','btn primary'):''}</div><div class="member-row"><div class="avatar">${m.photo?`<img src="${esc(m.photo)}">`:initials(m.name)}</div><div><div>${esc(m.bio||'')}</div><div class="muted">Joined ${date(m.joined_on)}</div>${user.role==='admin'?`<div class="muted">${esc(m.phone||'No phone added')}${m.active?'':' · Pending approval'}</div>`:''}</div></div><div class="section-head"><div><h2>Tour history</h2></div></div>${tours.map(t=>`<div class="activity-row">${esc(t.title)}<span class="grow"></span>${esc(t.status)} · ${date(t.start_at)}</div>`).join('')||'<div class="muted">No tour history yet.</div>'}${(user.role==='admin'||id===user.member_id)?`<div class="section-head"><div><h2>Payment history</h2></div></div>${payments.map(p=>`<div class="activity-row">${esc(p.tour)} · ${date(p.paid_at)} · ${money(p.amount)}<span class="grow"></span>${btn('Receipt','openReceipt(\''+esc(p.receipt)+'\')')}</div>`).join('')||'<div class="muted">No payment records yet.</div>'}`:''}`)}async function saveAnnouncement(e){e.preventDefault();try{await api('/announcements',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await boot();go('Admin');toast('Announcement published')}catch(x){toast(x.message)}}async function deleteAnnouncement(id){if(!confirm('Remove this announcement?'))return;await api('/announcements/'+id,{method:'DELETE'});await boot();go('Admin')}function toggleTheme(){const t=document.documentElement.dataset.theme==='light'?'dark':'light';setTheme(t)}function setChatTheme(theme){if(!['dark','light'].includes(theme))return;chatTheme=theme;localStorage.setItem('fg-chat-theme',theme);const panel=document.querySelector('#chatWidgetPanel');if(panel)panel.dataset.chatTheme=theme;document.querySelectorAll('#chatThemePanel [data-theme-choice]').forEach(x=>x.classList.toggle('selected',x.dataset.themeChoice===theme));toast(theme==='dark'?'Dark chat theme selected':'Light chat theme selected')}function setTheme(theme){if(!['dark','light'].includes(theme))return;document.documentElement.dataset.theme=theme;localStorage.setItem('fg-theme',theme);const b=document.querySelector('.theme-corner-toggle');if(b){b.textContent=theme==='light'?'◐':'☼';b.title=theme==='light'?'Switch to dark theme':'Switch to light theme'}toast(theme==='dark'?'Dark green theme selected':'Light green theme selected')}
async function loadPolls(){const grid=document.querySelector('#chatPollGrid');if(!grid)return;try{const polls=await api('/polls');grid.innerHTML=polls.map(p=>`<article class="card poll-card"><div class="poll-head"><div><h3>${esc(p.title)}</h3><small>${p.total} vote${p.total===1?'':'s'} · ${p.active&&p.canVote?'Open':'Closed'}</small></div>${user.role==='admin'?`<div class="poll-admin">${p.active?`<button class="btn ghost" data-action="closePoll" data-args="[${p.id}]">Close</button>`:''}<button class="btn ghost" data-action="deletePoll" data-args="[${p.id}]">Delete</button></div>`:''}</div><form data-submit="votePoll" data-id="${p.id}" class="poll-options">${p.options.map(o=>{const percent=p.total?Math.round(o.votes*100/p.total):0;return `<label class="poll-option ${p.myVote===o.id?'voted':''}"><span class="poll-option-line">${p.canVote?`<input type="radio" name="optionId" value="${o.id}" ${p.myVote===o.id?'checked':''} required>`:''}<b>${esc(o.label)}</b><span class="grow"></span>${p.myVote||!p.canVote?`<small>${o.votes} · ${percent}%</small>`:''}</span>${p.myVote||!p.canVote?`<i class="poll-bar" style="width:${percent}%"></i>`:''}</label>`}).join('')}${p.canVote?`<button class="btn primary">${p.myVote?'Update vote':'Vote'}</button>`:''}</form>${p.ends_at?`<small class="muted">Closes ${date(p.ends_at)}</small>`:''}</article>`).join('')||'<div class="empty">No polls yet.</div>'}catch(e){grid.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function newPoll(){modal('Create a poll','Add a question and at least two choices.',`<form class="form" data-submit="createPoll"><div class="field"><label>Question</label><input name="title" maxlength="180" required></div><div class="field"><label>Choices — add 2 to 8</label>${Array.from({length:8},(_,i)=>`<input name="options" maxlength="120" placeholder="Choice ${i+1}" ${i<2?'required':''}>`).join('')}</div><div class="field"><label>Close date (optional)</label><input name="ends_at" type="datetime-local"></div><button class="btn primary">Publish poll</button></form>`)}
async function createPoll(e){e.preventDefault();const fd=new FormData(e.target),options=fd.getAll('options').map(x=>x.trim()).filter(Boolean),ends=fd.get('ends_at');try{await api('/polls',{method:'POST',body:JSON.stringify({title:fd.get('title'),options,ends_at:ends?new Date(ends).toISOString():null})});document.querySelector('.overlay')?.remove();await loadPolls();toast('Poll published')}catch(x){toast(x.message)}}
async function votePoll(e,id){e.preventDefault();const optionId=Number(new FormData(e.target).get('optionId'));if(!optionId)return;try{await api(`/polls/${id}/vote`,{method:'POST',body:JSON.stringify({optionId})});await loadPolls();toast('Your vote was saved')}catch(x){toast(x.message)}}
async function closePoll(id){try{await api(`/polls/${id}`,{method:'PATCH',body:JSON.stringify({active:false})});await loadPolls()}catch(e){toast(e.message)}}
async function deletePoll(id){if(!confirm('Delete this poll and its votes?'))return;try{await api(`/polls/${id}`,{method:'DELETE'});await loadPolls()}catch(e){toast(e.message)}}function locationsPage(){const tours=data.tours.filter(t=>['Ongoing','Upcoming'].includes(t.status));const chosen=Number(window.selectedLocationTour)||tours[0]?.id;const t=tours.find(x=>x.id===chosen)||tours[0];if(!t)return '<div class="section-head"><div><h2>Locations</h2><p>Create a tour and add route coordinates to view the live map.</p></div></div><div class="empty">No active or upcoming tours yet.</div>';window.selectedLocationTour=t.id;return `<div class="section-head"><div><h2>Live tour locations</h2><p>Sharing is optional. Members choose when to share; locations expire after three minutes.</p></div></div><div class="card location-toolbar"><div class="field"><label>Tour</label><select id="locationTour" data-action="selectLocationTour">${tours.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(x.title)} · ${esc(x.status)}</option>`).join('')}</select></div><div class="field"><label>Travel mode</label><select id="travelMode"><option value="bus">🚌 Bus</option><option value="train">🚆 Train</option></select></div><div class="location-actions"><button class="btn primary" data-action="shareLocation" data-args="[${t.id}]">Share my location</button><button class="btn" data-action="stopLocation" data-args="[${t.id}]">Stop sharing</button></div></div><div class="map-card"><div id="liveMap" aria-label="Live tour map"></div><div class="map-legend"><span>● Planned tour route</span><span>📍 Shared member locations</span><span id="locationStatus">Location sharing is off</span></div></div><div class="location-list" id="locationList"></div><p class="muted location-privacy">Only signed-in tour participants and admins can view live locations. Browser location permission and localhost or HTTPS are required.</p>`}
function stopLocationWatch(){if(window.locationWatch!=null){navigator.geolocation.clearWatch(window.locationWatch);window.locationWatch=null}clearInterval(window.locationPoll)}
async function shareLocation(id){if(!navigator.geolocation||!window.isSecureContext){toast('Location sharing requires browser support and localhost or HTTPS');return}stopLocationWatch();window.lastLocationPost=0;window.locationWatch=navigator.geolocation.watchPosition(async p=>{if(Date.now()-window.lastLocationPost<8000)return;window.lastLocationPost=Date.now();try{await api(`/tours/${id}/location`,{method:'POST',body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,vehicle:document.querySelector('#travelMode')?.value||'bus'})});const el=document.querySelector('#locationStatus');if(el)el.textContent='Sharing your live location'}catch(e){toast(e.message);stopLocationWatch()}},e=>toast(e.message),{enableHighAccuracy:true,maximumAge:5000,timeout:20000})}
async function stopLocation(id){stopLocationWatch();try{await api(`/tours/${id}/location`,{method:'DELETE'});toast('Location sharing stopped');await boot();go('Locations')}catch(e){toast(e.message)}}
async function refreshLocations(id){try{const rows=await api(`/tours/${id}/locations`),list=document.querySelector('#locationList');if(list)list.innerHTML=rows.map(x=>`<div class="activity-row"><b>${esc(x.name)}</b><span class="grow">${x.vehicle==='train'?'🚆':'🚌'} ${esc(x.vehicle)} · ${new Date(x.updated_at+'Z').toLocaleTimeString()}</span></div>`).join('')||'<div class="muted">No one is sharing a location right now.</div>';if(window.liveMap){window.liveMarkers=window.liveMarkers||{};rows.forEach(x=>{const k=String(x.member_id),icon=L.divIcon({className:'vehicle-marker',html:x.vehicle==='train'?'🚆':'🚌',iconSize:[36,36]});if(window.liveMarkers[k])window.liveMarkers[k].setLatLng([x.latitude,x.longitude]);else window.liveMarkers[k]=L.marker([x.latitude,x.longitude],{icon}).addTo(window.liveMap).bindPopup(esc(x.name))})}}catch(e){}}
function startLocationView(){stopLocationWatch();const el=document.querySelector('#liveMap'),id=Number(document.querySelector('#locationTour')?.value),t=data.tours.find(x=>x.id===id);if(!el||!t||!window.L)return;const pts=t.stops.filter(x=>x.lat!=null&&x.lon!=null).map(x=>[x.lat,x.lon]);if(t.lat!=null&&t.lon!=null)pts.push([t.lat,t.lon]);if(!pts.length){el.innerHTML='<div class="empty map-empty">Add destination coordinates or route stop coordinates in tour settings to display the map.</div>';return}window.liveMap=L.map(el,{scrollWheelZoom:false});window.liveMarkers={};L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(window.liveMap);if(pts.length>1)L.polyline(pts,{color:'#38ad6b',weight:5,dashArray:'9 9'}).addTo(window.liveMap);if(pts.length){pts.forEach((x,i)=>L.circleMarker(x,{radius:6,color:'#38ad6b'}).addTo(window.liveMap).bindPopup(esc(t.stops[i]?.title||t.destination)));window.liveMap.fitBounds(pts,{padding:[35,35]})}refreshLocations(id);window.locationPoll=setInterval(()=>refreshLocations(id),8000);setTimeout(()=>window.liveMap?.invalidateSize(),100)}let chatConversations=[],chatPeople=[],chatActive=null,chatMessages=[],chatSource=null,chatReplyTo=null,chatTypingTimer=null;
function chatPage(){return `<div class="section-head chat-section-title"><div><h2>Chats</h2><p>Private conversations and the Friends Group</p></div><span class="badge complete" id="chatConnection">Connecting…</span></div><section class="card chat-layout"><aside class="chat-sidebar"><div class="chat-side-head"><b>Conversations</b><button class="btn ghost" data-chat="new">＋ New</button></div><input class="chat-search" id="chatSearch" placeholder="Search messages…"><div id="chatConversationList"><div class="empty">Loading chats…</div></div><section class="chat-directory"><div class="chat-directory-head"><b>Members inbox</b><button class="btn ghost chat-calls-link" data-chat="callHistory">☎ Calls</button></div><div id="chatMemberDirectory"><div class="empty">Loading members…</div></div></section><label class="chat-privacy"><input type="checkbox" id="chatPresence" checked> Show my online status</label></aside><div class="chat-main"><header class="chat-active-head"><div><b id="chatActiveTitle">Select a conversation</b><small id="chatActiveStatus"></small></div><div class="chat-call-actions"><button class="btn ghost" data-chat="roster" title="Show member list">☷</button><button class="call-action audio-call" data-chat="audio" title="Start audio call"><span>☎</span><small>Audio</small></button><button class="call-action video-call" data-chat="video" title="Start video call"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 10.5 21 7v10l-6-3.5M4 6h10a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Z"/></svg><small>Video</small></button></div></header><div id="chatPeopleStrip" class="chat-people-strip"></div><div id="chatMessages" class="chat-messages" aria-live="polite"><div class="empty">Choose a conversation to start chatting.</div></div><div id="chatTyping" class="chat-typing"></div><div id="chatReplyBar" class="chat-reply-bar" hidden></div><div id="chatRecordingStatus" class="chat-recording-status" hidden></div><form class="chat-compose" id="chatCompose"><button type="button" class="btn ghost" data-chat="emoji" title="Emoji">☺</button><textarea name="body" id="chatInput" maxlength="2000" rows="1" placeholder="Write a message…" aria-label="Write a message"></textarea><button class="btn primary">Send</button></form><div class="chat-extra"><button class="btn ghost" data-chat="attach">📎 Attach</button><input type="file" id="chatFile" hidden accept="image/*,video/*,audio/*,.pdf,.txt,.doc,.docx,.zip"><button class="btn ghost" data-chat="voice">🎙 Voice note</button><button class="btn ghost chat-poll-trigger" data-chat="polls">📊 Polls</button><button class="btn ghost chat-theme-trigger" data-chat="themes">◐ Theme</button><button class="btn ghost" data-chat="location">📍 Share location</button><button class="btn ghost" data-chat="liveLocation">🛰 Live location</button><button class="btn ghost" data-chat="stopLiveLocation">⏹ Stop sharing</button><span id="chatUploadStatus"></span></div><section id="chatPollPanel" class="chat-poll-panel" hidden><header><b>Group polls</b><button type="button" class="btn ghost" data-chat="polls">Close</button></header><div id="chatPollGrid"><div class="empty">Loading polls…</div></div></section><section id="chatThemePanel" class="chat-poll-panel chat-theme-panel" hidden><header><b>Chat appearance</b><button type="button" class="btn ghost" data-chat="themes">Close</button></header><div class="chat-theme-choices"><button class="theme-choice" data-chat="setChatTheme" data-theme-choice="dark"><span class="theme-swatch dark-swatch">◐</span><b>Dark green</b><small>Deep green surfaces</small></button><button class="theme-choice" data-chat="setChatTheme" data-theme-choice="light"><span class="theme-swatch light-swatch">☼</span><b>Light green</b><small>Bright green surfaces</small></button></div></section></div><aside class="chat-roster"><h3 id="chatRosterTitle">Friends Group members</h3><div id="chatRoster"></div></aside></section><div id="chatLightbox" class="chat-lightbox" hidden></div><div id="chatCallOverlay" class="chat-call-overlay" hidden></div><div id="chatEmojiPicker" class="chat-emoji-picker" hidden></div>`}
function initChatLauncher(){const app=document.querySelector('#app');if(!app||document.querySelector('#chatWidgetPanel'))return;const panel=document.createElement('section');panel.id='chatWidgetPanel';panel.className='chat-widget-panel';panel.dataset.chatTheme=localStorage.getItem('fg-chat-theme')||'dark';chatTheme=panel.dataset.chatTheme;panel.hidden=true;panel.innerHTML=`<div class="chat-widget-head"><b>Friends chat</b><div><button class="btn ghost" data-chat-expand title="Expand chat">⤢</button><button class="btn ghost" data-chat-close title="Close chat">×</button></div></div>${chatPage()}`;app.append(panel);panel.addEventListener('click',e=>{if(e.target.closest('[data-voice-stop]'))window.activeVoiceRecorder?.stop();if(e.target.closest('[data-chat-expand]'))panel.classList.toggle('expanded');if(e.target.closest('[data-chat-close]'))toggleChatWidget(false)})}
function toggleChatWidget(force){const panel=document.querySelector('#chatWidgetPanel');if(!panel)return;const open=force===undefined?panel.hidden:!!force;panel.hidden=!open;if(open)initChat();else{window.activeVoiceRecorder?.stop();window.chatSource?.close();window.chatSource=null}}async function initChat(){if(window.chatSource){window.chatSource.close();window.chatSource=null}if(!document.querySelector('#chatMessages'))return;await refreshConversations();if(chatActive)await loadChatMessages();window.chatSource=new EventSource('/api/chat/stream');window.chatSource.onopen=()=>{const x=document.querySelector('#chatConnection');if(x)x.textContent='Live';refreshConversations()};window.chatSource.onerror=()=>{const x=document.querySelector('#chatConnection');if(x)x.textContent='Reconnecting…'};window.chatSource.onmessage=e=>{try{handleChatEvent(JSON.parse(e.data))}catch{}};document.querySelector('#chatCompose').onsubmit=sendChatMessage;document.querySelector('#chatInput').oninput=()=>{if(!chatActive)return;api(`/chat/conversations/${chatActive}/typing`,{method:'POST',body:JSON.stringify({typing:true})}).catch(()=>{});clearTimeout(chatTypingTimer);chatTypingTimer=setTimeout(()=>api(`/chat/conversations/${chatActive}/typing`,{method:'POST',body:JSON.stringify({typing:false})}).catch(()=>{}),900)};document.querySelector('#chatSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchChat(e.target.value)}};document.querySelector('#chatPresence').onchange=e=>api('/chat/presence',{method:'POST',body:JSON.stringify({visible:e.target.checked})}).catch(x=>toast(x.message));document.querySelector('.chat-layout').onclick=chatClick;document.querySelector('#chatMessages').onclick=chatMessageClick;document.querySelector('#chatFile').onchange=uploadChatFile;}
async function refreshConversations(){try{chatConversations=await api('/chat/conversations');const list=document.querySelector('#chatConversationList');if(!list)return;const unreadTotal=chatConversations.reduce((n,c)=>n+Number(c.unread||0),0),unreadBadge=document.querySelector('#chatHeaderUnread');if(unreadBadge){unreadBadge.hidden=!unreadTotal;unreadBadge.textContent=unreadTotal>99?'99+':String(unreadTotal)}list.innerHTML=chatConversations.map(c=>`<button class="chat-conversation ${c.id===chatActive?'active':''}" data-cid="${c.id}"><span class="chat-avatar">${c.type==='group'?'👥':esc((c.peer?.name||'?').slice(0,1))}</span><span class="chat-conv-copy"><b>${esc(c.type==='group'?c.title:(c.peer?.name||'Member'))}</b><small>${esc(c.last_body||'No messages yet')}</small></span>${c.unread?`<i class="chat-unread">${c.unread}</i>`:''}${c.peer?.online?'<i class="chat-online"></i>':''}</button>`).join('')||'<div class="empty">No conversations yet.</div>';chatPeople=await api('/chat/people');renderChatDirectory();if(chatActive&&!chatConversations.some(c=>c.id===chatActive))chatActive=null;if(!chatActive&&chatConversations.length)chatActive=chatConversations.find(c=>c.id===1)?.id||chatConversations[0].id;if(chatActive)await selectChat(chatActive,false)}catch(e){toast(e.message)}}
function renderChatDirectory(){const el=document.querySelector('#chatMemberDirectory');if(!el)return;el.innerHTML=chatPeople.map((m,i)=>{const c=chatConversations.find(x=>x.id===m.conversation_id),preview=c?.last_body||'Open private inbox';return `<button class="chat-member-inbox ${c?.id===chatActive?'active':''}" data-member-inbox="${m.id}" title="Open private chat with ${esc(m.name)}"><span class="chat-member-number">${String(i+1).padStart(2,'0')}</span><span class="chat-directory-avatar">${m.photo?`<img src="${esc(m.photo)}" alt="">`:esc(initials(m.name))}<i class="${m.online?'online':''}"></i></span><span class="chat-directory-copy"><b>${esc(m.name)}</b><small>${esc(preview)}</small></span></button>`}).join('')||'<div class="empty">No other members yet.</div>'}async function openMemberInbox(id){const member=chatPeople.find(m=>m.id===id);if(!member)return;try{let c=chatConversations.find(x=>x.id===member.conversation_id);if(!c)c=await api('/chat/conversations',{method:'POST',body:JSON.stringify({memberId:id})});await refreshConversations();await selectChat(c.id)}catch(e){toast(e.message)}}
async function selectChat(id,load=true){chatActive=Number(id);const c=chatConversations.find(x=>x.id===chatActive);if(!c)return;document.querySelectorAll('.chat-conversation').forEach(x=>x.classList.toggle('active',Number(x.dataset.cid)===chatActive));document.querySelector('#chatActiveTitle').textContent=c.type==='group'?c.title:(c.peer?.name||'Private chat');document.querySelector('#chatActiveStatus').textContent=c.type==='group'?`${c.members.length+1} members`:c.peer?.online?'Online':c.peer?.last_seen?`Last seen ${new Date(c.peer.last_seen+'Z').toLocaleString()}`:'Offline';const self=data.members.find(m=>m.id===user.member_id),people=[...(c.members||[]),...(self?[{...self,online:true,visible:1}]:[])],strip=document.querySelector('#chatPeopleStrip');if(strip)strip.innerHTML=people.map(m=>`<div class="chat-person ${m.online&&m.visible?'online':''}" title="${esc(m.name)} · ${m.online&&m.visible?'Active':'Offline'}"><span class="chat-person-avatar">${m.photo?`<img src="${esc(m.photo)}" alt="">`:esc(initials(m.name))}<i></i></span><small>${esc(m.name.split(' ')[0])}</small></div>`).join('');const roster=document.querySelector('#chatRoster'),rosterTitle=document.querySelector('#chatRosterTitle');if(roster){const ordered=[...people].sort((a,b)=>a.name.localeCompare(b.name));if(rosterTitle)rosterTitle.textContent=`${c.type==='group'?c.title:'Chat'} · ${ordered.length} members`;roster.innerHTML=ordered.map((m,i)=>`<div class="chat-roster-person"><span class="chat-roster-index">${String(i+1).padStart(2,'0')}</span><span class="chat-roster-avatar">${m.photo?`<img src="${esc(m.photo)}" alt="">`:esc(initials(m.name))}<i class="${m.online&&m.visible?'online':''}"></i></span><span class="chat-roster-name"><b>${esc(m.name)}</b><small>${m.online&&m.visible?'Active':'Offline'}</small></span></div>`).join('')}if(load)await loadChatMessages();await api(`/chat/conversations/${chatActive}/read`,{method:'POST'}).catch(()=>{})}
async function loadChatMessages(before){const pane=document.querySelector('#chatMessages');if(!pane||!chatActive)return;try{const url=`/chat/conversations/${chatActive}/messages${before?'?before='+before:''}`,rows=await api(url);chatMessages=before?[...rows,...chatMessages]:rows;renderChatMessages(before);if(!before){pane.scrollTop=pane.scrollHeight;api(`/chat/conversations/${chatActive}/read`,{method:'POST'}).catch(()=>{})}else if(rows.length<50)document.querySelector('#chatOlder')?.remove()}catch(e){toast(e.message)}}
function renderChatMessages(prepend=false){const pane=document.querySelector('#chatMessages');if(!pane)return;const oldHeight=pane.scrollHeight,oldTop=pane.scrollTop;pane.innerHTML=`${chatMessages.length>=30?'<button class="btn ghost" id="chatOlder">Load older messages</button>':''}`+chatMessages.map(chatMessageHtml).join('')||'<div class="empty">No messages yet. Start the conversation.</div>';const older=pane.querySelector('#chatOlder');if(older)older.onclick=()=>loadChatMessages(chatMessages[0]?.id);if(prepend)pane.scrollTop=pane.scrollHeight-oldHeight+oldTop;}
