function showEmojiPicker(){const box=document.querySelector('#chatEmojiPicker');if(!box)return;box.hidden=!box.hidden;if(box.hidden)return;const input=document.querySelector('#chatInput'),render=(q='')=>{const term=q.trim().toLowerCase();box.innerHTML=`<input class="emoji-search" placeholder="Search emoji or category…" aria-label="Search emoji"><div class="emoji-picker-scroll">${Object.entries(emojiGroups).map(([name,items])=>{const list=items.split(' ').filter(e=>!term||name.toLowerCase().includes(term)||e.includes(term));return list.length?`<section><b>${name}</b><div class="emoji-grid">${list.map(e=>`<button type="button" class="emoji-choice" title="${e}">${e}</button>`).join('')}</div></section>`:''}).join('')||'<small>No matching emoji</small>'}</div>`;const search=box.querySelector('.emoji-search');search.value=q;search.oninput=()=>{const q=search.value,pos=search.selectionStart;render(q);const next=box.querySelector('.emoji-search');next.focus();next.setSelectionRange(pos,pos)};box.querySelectorAll('.emoji-choice').forEach(b=>b.onclick=()=>{const start=input.selectionStart,end=input.selectionEnd;input.setRangeText(b.textContent,start,end,'end');input.focus();box.hidden=true})};render();box.querySelector('.emoji-search').focus()}function chatMessageHtml(m){const mine=m.member_id===user.member_id,stamp=new Date(m.created_at+'Z').toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),attach=(m.attachments||[]).map(a=>a.mime.startsWith('image/')?`<img class="chat-media" src="${esc(a.url)}" data-full="${esc(a.url)}" alt="${esc(a.original_name)}">`:a.mime.startsWith('video/')?`<video class="chat-media" src="${esc(a.url)}" controls></video>`:a.mime.startsWith('audio/')?`<audio src="${esc(a.url)}" controls></audio>`:`<a href="${esc(a.url)}" target="_blank" rel="noopener">📎 ${esc(a.original_name)}</a>`).join(''),reactions=(m.reactions||[]).map(r=>`<button class="chat-reaction ${r.mine?'mine':''}" data-chat-reaction="${m.id}" data-emoji="${esc(r.emoji)}">${esc(r.emoji)} ${r.count}</button>`).join(''),ticks=mine?`<small class="chat-ticks">${m.read?'✓✓':m.delivered?'✓✓':'✓'}</small>`:'';return `<article class="chat-message ${mine?'mine':''}" data-mid="${m.id}"><div class="chat-author">${m.photo?`<img src="${esc(m.photo)}" alt="">`:''}<b>${esc(m.name)}</b><time>${stamp}${m.edited?' · edited':''}</time>${ticks}</div>${m.reply?`<blockquote class="chat-quoted">${esc(m.reply.name)}: ${esc(m.reply.body)}</blockquote>`:''}<div class="chat-body">${esc(m.body)}</div>${attach}${m.location?`<a class="chat-map" target="_blank" rel="noopener" href="https://maps.google.com/?q=${m.location.latitude},${m.location.longitude}">📍 View shared location ${m.location.live?'· Live':''}</a>`:''}<div class="chat-msg-tools"><button data-chat-reaction="${m.id}" data-emoji="👍">👍</button><button data-chat-reaction="${m.id}" data-emoji="❤️">❤️</button><button data-chat-reaction="${m.id}" data-emoji="😂">😂</button><button data-chat-reply="${m.id}">↩</button>${mine&&!m.deleted?`<button data-chat-edit="${m.id}">Edit</button><button data-chat-delete="${m.id}">Delete</button>`:''}</div><div class="chat-reactions">${reactions}</div></article>`}
async function sendChatMessage(e){e.preventDefault();const input=document.querySelector('#chatInput'),body=input.value.trim();if(!body||!chatActive)return;const replyToId=chatReplyTo;input.value='';chatReplyTo=null;document.querySelector('#chatReplyBar').hidden=true;try{await api(`/chat/conversations/${chatActive}/messages`,{method:'POST',body:JSON.stringify({body,replyToId})});await loadChatMessages()}catch(x){toast(x.message);input.value=body}}
function handleChatEvent(ev){if(ev.type==='message'&&ev.message){const m=ev.message;if(m.conversation_id===chatActive){if(!chatMessages.some(x=>x.id===m.id))chatMessages.push(m);renderChatMessages();const pane=document.querySelector('#chatMessages');pane.scrollTop=pane.scrollHeight;api(`/chat/conversations/${chatActive}/read`,{method:'POST'}).catch(()=>{})}refreshConversations()}else if(ev.type==='message-update'){const ix=chatMessages.findIndex(x=>x.id===ev.message?.id);if(ix>=0){chatMessages[ix]=ev.message;renderChatMessages()}}else if(ev.type==='receipt'){if(ev.conversationId===chatActive)loadChatMessages()}else if(ev.type==='conversations'||ev.type==='presence')refreshConversations();else if(ev.type==='typing'&&ev.conversationId===chatActive){const el=document.querySelector('#chatTyping');if(el)el.textContent=ev.typing?`${ev.name} is typing…`:''}else if(ev.type==='call-signal')receiveCallSignal(ev).catch(e=>toast(e.message));else if(ev.type==='location-update'||ev.type==='location-stop')loadChatMessages()}
async function chatClick(e){const member=e.target.closest('[data-member-inbox]');if(member){await openMemberInbox(Number(member.dataset.memberInbox));return}const conv=e.target.closest('[data-cid]');if(conv){selectChat(conv.dataset.cid);return}const b=e.target.closest('[data-chat]');if(!b)return;const act=b.dataset.chat;if(act==='new')return newChatModal();if(act==='polls'){const panel=document.querySelector('#chatPollPanel');if(panel){panel.hidden=!panel.hidden;document.querySelector('#chatThemePanel').hidden=true;if(!panel.hidden)loadPolls()}return}if(act==='themes'){const panel=document.querySelector('#chatThemePanel');if(panel){panel.hidden=!panel.hidden;document.querySelector('#chatPollPanel').hidden=true;panel.querySelectorAll('[data-theme-choice]').forEach(x=>x.classList.toggle('selected',x.dataset.themeChoice===chatTheme))}return}if(act==='setChatTheme'){setChatTheme(b.dataset.themeChoice);return}if(act==='callHistory')return showCallHistory();if(act==='roster'){document.querySelector('.chat-layout')?.classList.toggle('show-roster');return}if(act==='emoji'){showEmojiPicker();return}if(act==='attach'){document.querySelector('#chatFile').click();return}if(act==='voice')return recordVoiceNote();if(act==='location')return shareChatLocation(false);if(act==='liveLocation')return shareChatLocation(true);if(act==='stopLiveLocation'){const m=chatMessages.find(x=>x.location?.live&&x.member_id===user.member_id);if(!m)return toast('You have no active live location share in this chat');try{await api(`/chat/location/${m.location.id}/stop`,{method:'POST'});if(window.chatLocationWatch!==undefined){navigator.geolocation.clearWatch(window.chatLocationWatch);window.chatLocationWatch=undefined}await loadChatMessages();toast('Live location sharing stopped')}catch(x){toast(x.message)}return}if(act==='audio'||act==='video')return startCall(act==='video'?'video':'audio')}
async function chatMessageClick(e){const image=e.target.closest('[data-full]');if(image){const box=document.querySelector('#chatLightbox');box.innerHTML=`<img src="${esc(image.dataset.full)}" alt="">`;box.hidden=false;box.onclick=()=>box.hidden=true;return}const react=e.target.closest('[data-chat-reaction]');if(react){try{await api(`/chat/messages/${react.dataset.chatReaction}/reactions`,{method:'POST',body:JSON.stringify({emoji:react.dataset.emoji})})}catch(x){toast(x.message)}return}const reply=e.target.closest('[data-chat-reply]');if(reply){const m=chatMessages.find(x=>x.id===Number(reply.dataset.chatReply));chatReplyTo=m?.id||null;const bar=document.querySelector('#chatReplyBar');bar.textContent=`Replying to ${m?.name}: ${m?.body||''} · click to cancel`;bar.hidden=false;bar.onclick=()=>{chatReplyTo=null;bar.hidden=true};document.querySelector('#chatInput').focus();return}const edit=e.target.closest('[data-chat-edit]');if(edit){const m=chatMessages.find(x=>x.id===Number(edit.dataset.chatEdit)),body=prompt('Edit your message',m?.body);if(body!==null)try{await api(`/chat/messages/${m.id}`,{method:'PATCH',body:JSON.stringify({body})})}catch(x){toast(x.message)}return}const del=e.target.closest('[data-chat-delete]');if(del&&confirm('Delete this message?'))try{await api(`/chat/messages/${del.dataset.chatDelete}`,{method:'DELETE'})}catch(x){toast(x.message)}}
let rtcPeer=null,rtcLocal=null,rtcCall=null,rtcMode='audio',rtcStarted=0,rtcDurationTimer=null,rtcPendingCandidates=[];
async function signalCall(type,signal={}){if(!rtcCall)return;return api(`/chat/calls/${rtcCall.id}/signal`,{method:'POST',body:JSON.stringify({type,conversationId:rtcCall.conversationId,signal})})}
async function createPeer(mode){const cfg=await api('/chat/ice-config');rtcPeer=new RTCPeerConnection({iceServers:cfg.iceServers});rtcPendingCandidates=[];rtcPeer.onicecandidate=e=>{if(e.candidate)signalCall('candidate',e.candidate.toJSON()).catch(()=>{})};rtcPeer.ontrack=e=>{const v=document.querySelector('#chatRemoteVideo');if(v)v.srcObject=e.streams[0]};rtcPeer.onconnectionstatechange=()=>{if(['failed','disconnected','closed'].includes(rtcPeer?.connectionState||''))endCall(false)};if(mode==='video'){const v=document.querySelector('#chatLocalVideo');if(v&&rtcLocal)v.srcObject=rtcLocal}}
async function showCallHistory(){if(!chatActive)return toast('Choose a conversation first');const c=chatConversations.find(x=>x.id===chatActive);if(c?.type!=='direct')return toast('Open a private member inbox to view call history');try{const rows=await api(`/chat/calls?conversationId=${chatActive}`),fmt=x=>new Date(x.created_at+'Z').toLocaleString();const body=rows.length?`<div class="call-history-list">${rows.map(x=>`<article><span class="call-history-icon">${x.mode==='video'?'▣':'☎'}</span><span><b>${esc(x.peer)}</b><small>${esc(x.mode)} call · ${esc(x.status)} · ${esc(fmt(x.created_at))}</small></span></article>`).join('')}</div>`:'<div class="empty">No calls in this conversation yet.</div>';modal('Calls','Recent audio and video calls',body)}catch(e){toast(e.message)}}
async function startCall(mode){const c=chatConversations.find(x=>x.id===chatActive);if(!c||c.type!=='direct')return toast('Calls are available in private one-to-one chats');if(!navigator.mediaDevices?.getUserMedia)return toast('This browser does not support audio/video calls');try{rtcMode=mode;rtcLocal=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==='video'});rtcCall={id:crypto.randomUUID(),conversationId:chatActive,initiator:true};showCallUi(mode,'Calling…');await createPeer(mode);rtcLocal.getTracks().forEach(t=>rtcPeer.addTrack(t,rtcLocal));const offer=await rtcPeer.createOffer();await rtcPeer.setLocalDescription(offer);await signalCall('offer',{sdp:rtcPeer.localDescription.sdp});startCallDuration()}catch(e){cleanupCall();toast(e.message||'Could not start the call')}}
async function receiveCallSignal(ev){if(ev.signalType==='offer'){if(rtcCall)return api(`/chat/calls/${ev.callId}/signal`,{method:'POST',body:JSON.stringify({type:'reject',conversationId:ev.conversationId})});rtcCall={id:ev.callId,conversationId:ev.conversationId,initiator:false,callerId:ev.callerId};rtcMode=ev.mode;showCallUi(ev.mode,`Incoming ${ev.mode} call`,true);return}if(!rtcCall||rtcCall.id!==ev.callId)return;if(ev.signalType==='reject'||ev.signalType==='hangup'){toast(ev.signalType==='reject'?'Call declined':'Call ended');cleanupCall();return}if(ev.signalType==='answer'){await rtcPeer?.setRemoteDescription({type:'answer',sdp:ev.signal.sdp});for(const c of rtcPendingCandidates)await rtcPeer.addIceCandidate(c);rtcPendingCandidates=[];startCallDuration()}else if(ev.signalType==='candidate'){if(rtcPeer?.remoteDescription)await rtcPeer.addIceCandidate(ev.signal);else rtcPendingCandidates.push(ev.signal)}}
function showCallUi(mode,label,incoming=false){const box=document.querySelector('#chatCallOverlay');box.hidden=false;box.innerHTML=`<div class="chat-call-card"><h2>${esc(label)}</h2><div id="rtcDuration"></div><video id="chatRemoteVideo" autoplay playsinline ${mode==='audio'?'hidden':''}></video><video id="chatLocalVideo" autoplay muted playsinline ${mode==='audio'?'hidden':''}></video><div class="actions">${incoming?'<button class="btn primary" id="rtcAccept">Accept</button><button class="btn" id="rtcReject">Decline</button>':'<button class="btn" id="rtcMute">Mute</button>'}<button class="btn" id="rtcEnd">End call</button></div></div>`;box.querySelector('#rtcEnd').onclick=()=>endCall(true);if(incoming){box.querySelector('#rtcAccept').onclick=()=>acceptCall();box.querySelector('#rtcReject').onclick=async()=>{await signalCall('reject').catch(()=>{});cleanupCall()}}else box.querySelector('#rtcMute').onclick=e=>{const track=rtcLocal?.getAudioTracks()[0];if(track){track.enabled=!track.enabled;e.target.textContent=track.enabled?'Mute':'Unmute'}}}
async function acceptCall(){try{rtcLocal=await navigator.mediaDevices.getUserMedia({audio:true,video:rtcMode==='video'});await createPeer(rtcMode);rtcLocal.getTracks().forEach(t=>rtcPeer.addTrack(t,rtcLocal));await rtcPeer.setRemoteDescription({type:'offer',sdp:rtcCall.offerSdp||''});for(const c of rtcPendingCandidates)await rtcPeer.addIceCandidate(c);rtcPendingCandidates=[];const answer=await rtcPeer.createAnswer();await rtcPeer.setLocalDescription(answer);await signalCall('answer',{sdp:rtcPeer.localDescription.sdp});showCallUi(rtcMode,'Connected');startCallDuration()}catch(e){toast(e.message);cleanupCall()}}
async function endCall(notify=true){if(notify&&rtcCall)await signalCall('hangup').catch(()=>{});cleanupCall()}
function cleanupCall(){clearInterval(rtcDurationTimer);rtcDurationTimer=null;rtcPeer?.close();rtcPeer=null;rtcLocal?.getTracks().forEach(t=>t.stop());rtcLocal=null;rtcCall=null;rtcPendingCandidates=[];rtcStarted=0;const box=document.querySelector('#chatCallOverlay');if(box){box.hidden=true;box.replaceChildren()}}
function startCallDuration(){if(rtcStarted)return;rtcStarted=Date.now();rtcDurationTimer=setInterval(()=>{const el=document.querySelector('#rtcDuration');if(el){const n=Math.floor((Date.now()-rtcStarted)/1000);el.textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}},1000)}
async function searchChat(q){if(!chatActive)return;if(!q.trim())return loadChatMessages();try{chatMessages=await api(`/chat/conversations/${chatActive}/messages?q=${encodeURIComponent(q)}`);renderChatMessages()}catch(e){toast(e.message)}}
async function newChatModal(){const members=data.members.filter(m=>m.active&&m.id!==user.member_id);const overlay=modal('Start a chat','Choose one member for a private chat, or create a group.',`<div class="form"><button class="btn ghost" id="showGroupForm">＋ Create a group chat</button><div id="directChatChoices">${members.map(m=>`<button class="btn ghost" data-start-chat="${m.id}">${esc(m.name)}</button>`).join('')}</div><form class="form" id="createGroupForm" hidden><div class="field"><label>Group name</label><input name="title" maxlength="80" required></div><div class="field"><label>Members (select at least two)</label>${members.map(m=>`<label class="check-row"><input type="checkbox" name="memberIds" value="${m.id}"> ${esc(m.name)}</label>`).join('')}</div><button class="btn primary">Create group</button></form></div>`);overlay.addEventListener('click',async e=>{const b=e.target.closest('[data-start-chat]');if(b){try{const c=await api('/chat/conversations',{method:'POST',body:JSON.stringify({memberId:Number(b.dataset.startChat)})});overlay.remove();await refreshConversations();await selectChat(c.id)}catch(x){toast(x.message)}}if(e.target.closest('#showGroupForm')){document.querySelector('#createGroupForm').hidden=false;document.querySelector('#directChatChoices').hidden=true}});overlay.querySelector('#createGroupForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);try{const c=await api('/chat/conversations',{method:'POST',body:JSON.stringify({type:'group',title:fd.get('title'),memberIds:fd.getAll('memberIds').map(Number)})});overlay.remove();await refreshConversations();await selectChat(c.id)}catch(x){toast(x.message)}}}async function uploadChatFile(e){const file=e.target.files?.[0];e.target.value='';if(!file||!chatActive)return;const status=document.querySelector('#chatUploadStatus');status.textContent='Uploading…';const fd=new FormData();fd.append('file',file);fd.append('caption',document.querySelector('#chatInput').value.trim());try{await api(`/chat/conversations/${chatActive}/attachments`,{method:'POST',body:fd});status.textContent='';await loadChatMessages()}catch(x){status.textContent='';toast(x.message)}}
async function recordVoiceNote(){if(window.activeVoiceRecorder){window.activeVoiceRecorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Voice recording is not supported in this browser');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),recorder=new MediaRecorder(stream),chunks=[],status=document.querySelector('#chatRecordingStatus');window.activeVoiceRecorder=recorder;window.voiceRecordingStarted=Date.now();status.hidden=false;status.innerHTML='<span class="recording-dot"></span><b>Recording voice</b><strong id="voiceRecordingClock">00:00</strong><button type="button" class="btn ghost" data-voice-stop>Stop & send</button>';clearInterval(window.voiceRecordingTimer);window.voiceRecordingTimer=setInterval(()=>{const el=document.querySelector('#voiceRecordingClock');if(el){const n=Math.floor((Date.now()-window.voiceRecordingStarted)/1000);el.textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}},250);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{clearInterval(window.voiceRecordingTimer);window.activeVoiceRecorder=null;stream.getTracks().forEach(t=>t.stop());status.hidden=true;status.innerHTML='';if(!chunks.length)return;const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'}),file=new File([blob],`voice-${Date.now()}.webm`,{type:blob.type}),fd=new FormData();fd.append('file',file);const label=document.querySelector('#chatUploadStatus');label.textContent='Sending voice note…';try{await api(`/chat/conversations/${chatActive}/attachments`,{method:'POST',body:fd});await loadChatMessages()}catch(e){toast(e.message)}finally{label.textContent=''}};recorder.start(250)}catch(e){toast(e.message==='Permission denied'?'Allow microphone access to record a voice note':'Microphone could not be started. Check browser permission and try again')}}async function shareChatLocation(live){if(!chatActive)return;try{const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:12000}));const result=await api(`/chat/conversations/${chatActive}/location`,{method:'POST',body:JSON.stringify({mode:live?'live':'once',latitude:pos.coords.latitude,longitude:pos.coords.longitude,minutes:60})});await loadChatMessages();if(live){window.chatLocationWatch=navigator.geolocation.watchPosition(p=>api(`/chat/location/${result.id}/update`,{method:'POST',body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude})}).catch(()=>{}),()=>{}, {enableHighAccuracy:true});toast('Live location shared. Stop sharing from the message when finished.')}}catch(e){toast(e.message||'Location permission was not granted')}}function render(){if(!data)return;app.innerHTML=`<main class="shell">${header()}${view==='Home'?home():view==='Tours'?toursPage():view==='Locations'?locationsPage():view==='Chat'?chatPage():view==='Memories'?memories():view==='Members'?membersPage():view==='Payments'?paymentsPage():view==='Settings'?settingsPage():adminPage()}<footer class="section-head site-footer"><span class="muted">Members only · ${esc(data.group)}</span></footer></main>`;const hero=app.querySelector('.hero');if(hero&&data.settings.hero)hero.style.backgroundImage="linear-gradient(90deg,#11121cf5 0%,#10111bd9 43%,#12131d74 100%),url('"+data.settings.hero+"')";tickCountdowns();initCarousel();if(view==='Locations')startLocationView();if(view==='Memories')loadMemories();if(view==='Chat')initChat();initChatLauncher()}function modal(title,desc,body){const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<section class="modal"><button class="close" data-action="closeModal" data-args="[]">×</button><h2>${title}</h2><p>${desc}</p>${body}</section>`;overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});document.body.append(overlay);return overlay}function memberForm(){const o=modal('New member','Private profile details are only visible to admins.',`<form class="form two" data-submit="saveMember"><div class="field full"><label>Full name</label><input name="name" required></div><div class="field"><label>Nickname</label><input name="nickname"></div><div class="field"><label>Phone</label><input name="phone" type="tel"></div><div class="field full"><label>Short bio</label><textarea name="bio"></textarea></div><div class="field"><label>Login username (optional)</label><input name="username" minlength="3"></div><div class="field"><label>Login password (optional, 10+ characters)</label><input name="password" type="password"></div><div class="field full actions"><button type="button" class="btn" data-action="closeModal" data-args="[]">Cancelled</button><button class="btn primary">Add member</button></div></form>`);o.querySelector('input[name=username]').addEventListener('input',e=>{o.querySelector('input[name=password]').required=!!e.target.value})}async function saveMember(e){e.preventDefault();try{await api('/members',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('.overlay').remove();await boot();go('Members');toast('Member added')}catch(x){toast(x.message)}}function editMember(id){const m=data.members.find(x=>x.id===id);modal('Edit member','Manage profile, login access, and account status.',`<form class="form two" data-submit="updateMember" data-id="${id}"><div class="field full"><label>Name</label><input name="name" value="${esc(m.name)}" required></div><div class="field"><label>Nickname</label><input name="nickname" value="${esc(m.nickname)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(m.phone)}"></div><div class="field full"><label>Bio</label><textarea name="bio">${esc(m.bio)}</textarea></div><div class="field"><label>Account</label><select name="active"><option value="1" ${m.active?'selected':''}>Active</option><option value="0" ${!m.active?'selected':''}>Inactive</option></select></div><div class="field"><label>Profile photo</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp,image/gif"></div><fieldset class="field full tour-assignment"><legend>Tour history</legend>${data.tours.map(t=>`<label class="check-row"><input type="checkbox" name="tourIds" value="${t.id}" ${t.participants.some(p=>p.id===id)?'checked':''}> ${esc(t.title)} · ${esc(t.status)}</label>`).join('')||'<span class="muted">Create a tour first.</span>'}</fieldset><div class="field full actions"><button class="btn primary">Save</button></div></form>`)}async function updateMember(e,id){e.preventDefault();try{const fd=new FormData(e.target),photo=fd.get('photo'),values=Object.fromEntries(fd),tourIds=fd.getAll('tourIds').map(Number);delete values.photo;delete values.tourIds;await api('/members/'+id,{method:'PUT',body:JSON.stringify(values)});await api('/members/'+id+'/tours',{method:'PUT',body:JSON.stringify({tourIds})});if(photo?.size){const image=new FormData();image.append('photo',photo);await api('/members/'+id+'/photo',{method:'POST',body:image});}document.querySelector('.overlay').remove();await boot();toast('Member details saved')}catch(x){toast(x.message)}}function tourForm(t=null){const isEdit=!!t,members=data.members.filter(m=>m.active);modal(isEdit?'Tours Edit':'New tour','Set dates, status, route stops, and participants.',`<form class="form two" data-submit="saveTour" data-id="${isEdit?t.id:''}"><div class="field"><label>Tour title</label><input name="title" value="${esc(t?.title)}" required></div><div class="field"><label>Destination</label><input name="destination" value="${esc(t?.destination)}" required></div><div class="field"><label>Start — Bangladesh time</label><input name="start_at" type="datetime-local" value="${t?.start_at?esc(localDhaka(t.start_at)):''}"></div><div class="field"><label>End — Bangladesh time</label><input name="end_at" type="datetime-local" value="${t?.end_at?esc(localDhaka(t.end_at)):''}"></div><div class="field"><label>Contribution per person (৳)</label><input name="contribution" type="number" min="0" step="1" value="${Number(t?.contribution||0)}"></div><div class="field"><label>Tour budget (৳)</label><input name="budget" type="number" min="0" step="1" value="${Number(t?.budget||0)}"></div><div class="field"><label>Status</label><select name="status">${['Upcoming','Ongoing','Completed','Cancelled'].map(s=>`<option ${t?.status===s||!t&&s==='Upcoming'?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Latitude</label><input name="lat" type="number" step="any" value="${t?.lat||''}"></div><div class="field"><label>Longitude</label><input name="lon" type="number" step="any" value="${t?.lon||''}"></div><div class="field full"><label>Address</label><input name="address" value="${esc(t?.address)}"></div><div class="field"><label>Travel distance (km, if known)</label><input name="distance_km" type="number" min="0" step="0.1" value="${t?.distance_km??''}"></div><div class="field"><label>Video link (HTTPS, optional)</label><input name="video_url" type="url" placeholder="https://…" value="${esc(t?.video_url)}"></div><div class="field full"><label>Tour cover photo (optional)</label><input name="cover_file" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="field full"><label>Description and memorable moments</label><textarea name="description">${esc(t?.description)}</textarea></div><div class="field full"><label>Extra stops — one per line: name | address | latitude | longitude</label><textarea name="stops" placeholder="Jaflong | Sylhet | 25.16 | 92.01">${(t?.stops||[]).map(x=>[x.title,x.address,x.lat||'',x.lon||''].join(' | ')).join('\n')}</textarea></div><div class="field full"><label>Participants</label><div class="form two">${members.map(m=>`<label class="muted"><input type="checkbox" name="memberIds" value="${m.id}" ${(t?.participants||[]).some(p=>p.id===m.id)?'checked':''}> ${esc(m.name)}</label>`).join('')}</div></div><div class="field full actions"><button class="btn primary">${isEdit?'Save':'Create tour'}</button></div></form>`)}async function saveTour(e,id){e.preventDefault();const fd=new FormData(e.target),v=Object.fromEntries(fd),cover=fd.get('cover_file');delete v.cover_file;v.memberIds=fd.getAll('memberIds');const lines=(v.stops||'').split('\n').filter(Boolean);delete v.stops;v.stops=lines.map(line=>{const [title,address='',lat='',lon='']=line.split('|').map(x=>x.trim());return {title,address,lat,lon}});for(const key of ['start_at','end_at'])if(v[key])v[key]=new Date(v[key]+':00+06:00').toISOString();try{const result=await api('/tours'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(v)});const tid=id||result.id;await api('/tours/'+tid+'/stops',{method:'PUT',body:JSON.stringify({stops:v.stops})});if(cover?.size){const image=new FormData();image.append('image',cover);await api('/tours/'+tid+'/cover',{method:'POST',body:image})}document.querySelector('.overlay').remove();await boot();go('Tours');toast('Tour and route stops saved')}catch(x){toast(x.message)}}function paymentForm(tid,mid){const t=data.tours.find(x=>x.id===tid),m=t.participants.find(x=>x.id===mid),remaining=Math.max(0,t.contribution-m.paid);modal('Record payment','Verify the payment before recording it.',`<form class="form" data-submit="savePayment" data-tour="${tid}" data-member="${mid}"><div class="card"><b>${esc(m.name)} · ${esc(t.title)}</b><div class="muted">Paid ${money(m.paid)} · Balance ${money(remaining)}</div></div><div class="field"><label>Amount to pay (৳)</label><input name="amount" type="number" min="1" step="1" max="${remaining}" required></div><div class="field"><label>Payments Method</label><select name="method"><option>Cash</option><option>bKash</option><option>Nagad</option><option>Bank transfer</option><option>Other</option></select></div><div class="field"><label>Transaction reference (optional)</label><input name="reference"></div><button class="btn primary">Confirm payment and generate receipt</button></form>`)}async function savePayment(e,tid,mid){e.preventDefault();try{const v=await api(`/tours/${tid}/payments`,{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),member_id:mid})});document.querySelector('.overlay').remove();await boot();receiptModal(v.receipt);toast(v.smsSent?'Payment recorded; SMS provider accepted it':'Payment recorded; SMS not sent')}catch(x){toast(x.message)}}async function receiptModal(id){const p=await api('/receipts/'+id);const body=`<div class="receipt" id="receipt"><h2>${data.settings.logo?`<img class="receipt-logo" src="${esc(data.settings.logo)}" alt="">`:``}${esc(p.group)}</h2><p>Payments Receipt</p><hr><p><b>Receipt no:</b> ${esc(p.receipt)}</p><p><b>Members:</b> ${esc(p.name)}</p><p><b>Tours:</b> ${esc(p.title)}</p><p><b>Amount received:</b> ${money(p.amount)}</p><p><b>Previous balance:</b> ${money(Math.max(0,p.contribution-p.previous))} · <b>Balance after this payment:</b> ${money(p.remaining)}</p><p><b>Date:</b> ${date(p.paid_at)}</p><p><b>Method:</b> ${esc(p.method)} ${p.reference?'· '+esc(p.reference):''}</p><p><b>Status:</b> ${p.paid>=p.contribution?'Paid':'Partially paid'}</p><hr><small>This receipt confirms the recorded payment.</small></div><div class="actions" style="margin-top:14px">${btn('Copy SMS message','copySms(\''+esc(p.receipt)+'\',\''+esc(p.amount)+'\',\''+esc(p.remaining)+'\')')}${btn('Print / Save as PDF','printPage()','btn primary')}</div>`;modal('Payments Receipt','Print the receipt or copy and share the SMS message.',body)}function copySms(r,a,b){const s=`${data.group}: ৳${a} payment received. Receipt ${r}. Balance ৳${b}.`;navigator.clipboard.writeText(s).then(()=>toast('SMS message copied')).catch(()=>toast(s))}function tourDetail(id){const t=data.tours.find(x=>x.id===id);if(!t)return;const map=t.lat&&t.lon?`<a class="maplink" target="_blank" rel="noopener" href="https://www.google.com/maps?q=${t.lat},${t.lon}">Google Maps ↗</a>`:'';const detail=modal(esc(t.title),`${esc(t.destination)} · ${date(t.start_at)} ${map}`,`${t.description?`<p>${esc(t.description)}</p>`:''}${user.role==='admin'?`<div class="actions">${btn('Edit','editTour('+t.id+')')}${btn('Add expense','expenseForm('+t.id+')')}${btn('Add photos','photoForm('+t.id+')')}</div>`:''}${t.stops.length?`<div class="section-head"><div><h2>Route stops</h2></div></div>${t.stops.map(x=>`<div class="activity-row"><b>${esc(x.title)}</b><span class="grow">${esc(x.address)}</span>${x.lat&&x.lon?`<a class="maplink" href="https://www.google.com/maps?q=${x.lat},${x.lon}" target="_blank" rel="noopener">Map ↗</a>`:''}</div>`).join('')}`:''}${t.distance_km?`<div class="activity-row">Recorded travel distance <b>${esc(t.distance_km)} km</b></div>`:``}${t.video_url?`<p><a class="maplink" target="_blank" rel="noopener noreferrer" href="${esc(t.video_url)}">Watch trip video ↗</a></p>`:``}<div class="section-head"><div><h2>Participant contributions</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Members</th><th>Required</th><th>Paid</th><th>Balance</th><th>Status</th>${user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${t.participants.map(p=>{const remain=Math.max(0,t.contribution-p.paid),st=p.waived?'WAIVED':p.paid>=t.contribution?'PAID':p.paid?'PARTIAL':'PENDING';return `<tr><td><span class="avatar small">${p.photo?`<img src="${esc(p.photo)}" alt="">`:initials(p.name)}</span> ${esc(p.name)}</td><td>${money(t.contribution)}</td><td>${money(p.paid)}</td><td>${money(remain)}</td><td>${st}</td>${user.role==='admin'?`<td>${!p.waived&&remain?btn('+ Paid','paymentForm('+t.id+','+p.id+')'):''} ${!p.waived?btn('Waived','waive('+t.id+','+p.id+')','btn ghost'):''}</td>`:''}</tr>`}).join('')}</tbody></table></div>${user.role==='admin'?`<div class="section-head"><div><h2>Recorded expenses · ${money(t.expenses.reduce((a,x)=>a+x.amount,0))}</h2></div></div>${t.expenses.map(x=>`<div class="activity-row">${esc(x.label)}<span class="grow"></span>${money(x.amount)} ${btn('Delete','deleteExpense('+x.id+','+t.id+')','btn ghost')}</div>`).join('')||'<div class="muted">No expenses recorded.</div>'}`:''}${t.gallery.length?`<div class="section-head"><div><h2>Album photos</h2></div></div><div class="gallery">${t.gallery.map(g=>mediaCard({...g,title:t.title})).join('')}</div>`:''}`);if(t.lat&&t.lon){const box=document.createElement('div');box.innerHTML='<div id="tourMap"></div>';detail.querySelector('.modal').append(box);setTimeout(()=>{if(window.L){const mv=L.map('tourMap').setView([t.lat,t.lon],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(mv);L.marker([t.lat,t.lon]).addTo(mv).bindPopup(esc(t.destination)).openPopup()}},100)}}function expenseForm(id){modal('Tour expenses','Recorded expenses will appear in the tour details.',`<form class="form" data-submit="saveExpense" data-id="${id}"><div class="field"><label>Expense description</label><input name="label" required></div><div class="field"><label>Amount (৳)</label><input name="amount" type="number" min="1" step="1" required></div><button class="btn primary">Record expense</button></form>`)}async function saveExpense(e,id){e.preventDefault();try{await api(`/tours/${id}/expenses`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('.overlay').remove();await boot();tourDetail(id);toast('Expense saved')}catch(x){toast(x.message)}}function moveMemoryCard(source,target,x,y){if(!source||!target||source===target)return false;const r=target.getBoundingClientRect(),after=(y>r.top+r.height/2)||(Math.abs(y-(r.top+r.height/2))<r.height*.25&&x>r.left+r.width/2);target.parentNode.insertBefore(source,after?target.nextSibling:target);return true}
function suppressNextMemoryClick(){memorySuppressClick=true;setTimeout(()=>memorySuppressClick=false,900)}
function persistMemoryOrder(albumId){const grid=document.querySelector('#memoryGrid');if(!grid||!albumId)return;const photoIds=[...grid.querySelectorAll('[data-memory-photo]')].map(x=>Number(x.dataset.memoryPhoto));api(`/albums/${albumId}/reorder`,{method:'POST',body:JSON.stringify({photoIds})}).then(()=>toast('Photo order saved')).catch(async e=>{toast(e.message);await loadMemories()})}
function shiftMemoryPhoto(id,delta){const grid=document.querySelector('#memoryGrid');if(!grid||!memorySortAlbum)return;const cards=[...grid.querySelectorAll('[data-memory-photo]')],i=cards.findIndex(x=>Number(x.dataset.memoryPhoto)===id),next=i+delta;if(i<0||next<0||next>=cards.length)return;grid.insertBefore(cards[i],delta<0?cards[next]:cards[next].nextSibling);persistMemoryOrder(memorySortAlbum)}
function bindMemoryReorder(){const grid=document.querySelector('#memoryGrid');if(!grid)return;grid.ondragstart=e=>{if(e.target.closest('[data-memory-photo]'))e.preventDefault()};grid.onpointerdown=e=>{if(!memorySortAlbum)return;const card=e.target.closest('[data-memory-photo]');if(!card||!card.dataset.memoryPhoto||e.target.closest('button'))return;memoryTouchHold={card,pointerId:e.pointerId,x:e.clientX,y:e.clientY,type:e.pointerType};if(e.pointerType!=='mouse')memoryTouchHold.timer=setTimeout(()=>{if(!memoryTouchHold||memoryTouchHold.pointerId!==e.pointerId)return;memoryTouchDrag={card,pointerId:e.pointerId,moved:false};card.classList.add('reordering');try{card.setPointerCapture(e.pointerId)}catch{}toast('Photo ready — drag it to reorder')},500)};grid.onpointermove=e=>{const hold=memoryTouchHold;if(hold&&hold.pointerId===e.pointerId){if(hold.type==='mouse'){if(!memoryTouchDrag&&Math.hypot(e.clientX-hold.x,e.clientY-hold.y)>=4){memoryTouchDrag={card:hold.card,pointerId:e.pointerId,moved:false};hold.card.classList.add('reordering');try{hold.card.setPointerCapture(e.pointerId)}catch{}memoryTouchHold=null}}else if(!memoryTouchDrag&&Math.hypot(e.clientX-hold.x,e.clientY-hold.y)>14){clearTimeout(hold.timer);memoryTouchHold=null}}if(!memoryTouchDrag||memoryTouchDrag.pointerId!==e.pointerId)return;e.preventDefault();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-memory-photo]');if(target&&target.closest('#memoryGrid')===grid&&target!==memoryTouchDrag.card)memoryTouchDrag.moved=moveMemoryCard(memoryTouchDrag.card,target,e.clientX,e.clientY)||memoryTouchDrag.moved};const finish=e=>{if(memoryTouchHold?.pointerId===e.pointerId){clearTimeout(memoryTouchHold.timer);memoryTouchHold=null}if(!memoryTouchDrag||memoryTouchDrag.pointerId!==e.pointerId)return;const {card,moved}=memoryTouchDrag;card.classList.remove('reordering');memoryTouchDrag=null;if(moved){memorySuppressClick=true;setTimeout(()=>memorySuppressClick=false,350);persistMemoryOrder(memorySortAlbum)}};grid.onpointerup=finish;grid.onpointercancel=finish;grid.oncontextmenu=e=>{if(e.target.closest('[data-memory-photo]'))e.preventDefault()}}

function ownedMemoryAlbums(){return memoryAlbums.filter(a=>Number(a.owner_member_id)===Number(user.member_id))}
function newMemoryAlbum(){modal('Create a personal album','Choose a name and decide whether other group members can view it.',`<form class="form" data-submit="createMemoryAlbum"><div class="field"><label>Album name</label><input name="title" maxlength="120" minlength="2" required placeholder="Weekend moments"></div><div class="field"><label>Who can see this album?</label><select name="visibility"><option value="private">Private — only me</option><option value="public">Public — group members</option></select></div><button class="btn primary">Create album</button></form>`)}
async function createMemoryAlbum(e){e.preventDefault();try{const form=Object.fromEntries(new FormData(e.target));const result=await api('/albums',{method:'POST',body:JSON.stringify(form)});document.querySelector('.overlay')?.remove();memoryAlbumFilter=String(result.id);await loadMemories();toast('Album created')}catch(x){toast(x.message)}}
function editMemoryAlbum(id){const a=memoryAlbums.find(x=>x.id===id);if(!a||a.owner_member_id!==user.member_id)return;modal('Album settings','Change the album name or visibility at any time.',`<form class="form" data-submit="saveMemoryAlbum" data-id="${a.id}"><div class="field"><label>Album name</label><input name="title" maxlength="120" value="${esc(a.title)}" required></div><div class="field"><label>Who can see this album?</label><select name="visibility"><option value="private" ${a.visibility==='private'?'selected':''}>Private — only me</option><option value="public" ${a.visibility==='public'?'selected':''}>Public — group members</option></select></div><button class="btn primary">Save album</button></form>`)}
async function saveMemoryAlbum(e,id){e.preventDefault();try{await api('/albums/'+id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('.overlay')?.remove();await loadMemories();toast('Album updated')}catch(x){toast(x.message)}}
async function deleteMemoryAlbum(id){const a=memoryAlbums.find(x=>x.id===id);if(!a||a.owner_member_id!==user.member_id)return;if(!confirm('Delete this album and all its photos?'))return;try{await api('/albums/'+id,{method:'DELETE'});if(memoryAlbumFilter===String(id))memoryAlbumFilter='all';await loadMemories();toast('Album deleted')}catch(x){toast(x.message)}}
function photoForm(id=null){const albums=ownedMemoryAlbums();if(!albums.length){toast('Create an album first, then upload photos to it');return newMemoryAlbum()}const initial=Number(id)||Number(memoryAlbumFilter)||albums[0].id;modal('Upload photos','Choose one of your albums. Photos can be added at any time, without choosing a tour.',`<form class="form" data-submit="savePhotos"><div class="field"><label>Your album</label><select name="album_id" required>${albums.map(a=>`<option value="${a.id}" ${a.id===initial?'selected':''}>${esc(a.title)} · ${a.visibility==='private'?'Private':'Public'}</option>`).join('')}</select></div><div class="field"><label>Photos (up to 10 · 5 MB each)</label><input name="photos" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple required></div><div class="field"><label>Caption (optional)</label><input name="caption" maxlength="300"></div><div class="field"><label>Location (optional)</label><input name="location" maxlength="200"></div><div class="field"><label>Photo date (optional)</label><input name="taken_at" type="date"></div><button class="btn primary">Upload photos</button></form>`)}
async function savePhotos(e){e.preventDefault();const fd=new FormData(e.target),id=fd.get('album_id');try{await api('/albums/'+id+'/photos',{method:'POST',body:fd});document.querySelector('.overlay')?.remove();memoryAlbumFilter=String(id);await loadMemories();toast('Photos uploaded to your album')}catch(x){toast(x.message)}}
async function loadMemories(){const grid=document.querySelector('#memoryGrid');if(!grid)return;try{memoryAlbums=await api('/albums');const sel=document.querySelector('#memoryAlbumFilter'),previous=memoryAlbumFilter||sel?.value||'all';if(sel){sel.innerHTML='<option value="all">All albums</option>'+memoryAlbums.map(a=>`<option value="${a.id}">${esc(a.title)} · ${a.visibility==='private'?'Private':'Public'}</option>`).join('');sel.value=memoryAlbums.some(a=>String(a.id)===previous)||previous==='all'?previous:'all';memoryAlbumFilter=sel.value;sel.onchange=()=>{memoryAlbumFilter=sel.value;filterMemories()}}const albumList=document.querySelector('#memoryAlbumList');if(albumList)albumList.innerHTML=memoryAlbums.map(a=>`<article class="memory-album-card ${String(a.id)===memoryAlbumFilter?'selected':''}"><button class="memory-album-open" data-memory-album="${a.id}"><span class="memory-album-icon">${a.visibility==='private'?'🔒':'▧'}</span><span><b>${esc(a.title)}</b><small>${Number(a.owner_member_id)===Number(user.member_id)?'Your album':a.owner_name?esc(a.owner_name)+"'s album":'Tour album'} · ${a.photos.length} photo${a.photos.length===1?'':'s'} · ${a.visibility==='private'?'Private':'Public'}</small></span></button>${a.owner_member_id===user.member_id?`<div class="memory-album-tools"><button class="btn ghost" data-action="editMemoryAlbum" data-args="[${a.id}]">Settings</button><button class="btn ghost" data-action="deleteMemoryAlbum" data-args="[${a.id}]">Delete</button></div>`:''}</article>`).join('')||'<div class="empty">No albums yet. Create one to keep your photos.</div>';const filtered=memoryAlbums.filter(a=>memoryAlbumFilter==='all'||String(a.id)===memoryAlbumFilter).flatMap(a=>a.photos.map(p=>({...p,album_title:a.title,owner_name:a.owner_name,owner_member_id:a.owner_member_id,visibility:a.visibility,title:a.tour_title||a.title})));const label=document.querySelector('#memoryResultLabel');if(label)label.textContent=memoryAlbumFilter==='all'?`${filtered.length} photos across ${memoryAlbums.length} albums`:memoryAlbums.find(a=>String(a.id)===memoryAlbumFilter)?.title||'Album photos';filterMemories()}catch(e){grid.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function filterMemories(){const q=(document.querySelector('#memorySearch')?.value||'').trim().toLowerCase(),chosen=document.querySelector('#memoryAlbumFilter')?.value||memoryAlbumFilter||'all',albums=memoryAlbums.filter(a=>chosen==='all'||String(a.id)===chosen),sortable=albums.length===1&&Number(albums[0].owner_member_id)===Number(user.member_id)&&!q;memorySortAlbum=sortable?albums[0].id:null;const photos=albums.flatMap(a=>a.photos.map(p=>({...p,album_title:a.title,owner_name:a.owner_name,owner_member_id:a.owner_member_id,visibility:a.visibility,title:a.tour_title||a.title,canReorder:sortable}))).filter(p=>(p.caption+' '+p.title+' '+p.album_title+' '+p.location+' '+p.owner_name).toLowerCase().includes(q));const grid=document.querySelector('#memoryGrid');if(grid){grid.innerHTML=photos.map(mediaCard).join('')||'<div class="empty">No photos in this album yet.</div>';grid.classList.toggle('memory-sort-enabled',sortable);const hint=document.querySelector('#memorySortHint');if(hint)hint.hidden=!sortable;bindMemoryReorder()}const label=document.querySelector('#memoryResultLabel');if(label)label.textContent=chosen==='all'?String(photos.length)+' photos across '+albums.length+' albums':albums[0]?.title||'Album photos'}
function tickCountdowns(){function update(){document.querySelectorAll('.countdown[data-date]').forEach(el=>{const target=new Date(el.dataset.date).getTime();if(!Number.isFinite(target)){el.innerHTML='<span class="muted">Date not set</span>';return}let ms=target-Date.now();if(ms<=0){el.innerHTML='<span class="muted">The trip has started!</span>';return}const vals=[Math.floor(ms/864e5),Math.floor(ms/36e5)%24,Math.floor(ms/6e4)%60,Math.floor(ms/1e3)%60];el.innerHTML=vals.map((v,i)=>`<div><b>${String(v).padStart(2,'0')}</b><small>${['Days','Hours','Minutes','Seconds'][i]}</small></div>`).join('')})}update();clearInterval(window.countdownTimer);window.countdownTimer=setInterval(update,1000)}function exportCsv(){window.location.href='/api/export.csv'}function downloadBackup(){window.location.href='/api/backup'}function printPage(){window.print()}function filterPayments(){const s=document.querySelector('#payFilter')?.value||'all';document.querySelectorAll('#paymentRows tr').forEach(r=>r.hidden=s!=='all'&&r.dataset.status!==s)}async function waive(tid,mid){try{const t=data.tours.find(x=>x.id===tid),p=t.participants.find(x=>x.id===mid);await api(`/tours/${tid}/participants/${mid}/waive`,{method:'POST'});await boot();toast('Contribution waived')}catch(e){toast(e.message)}}async function deleteExpense(id,tid){if(!confirm('Delete this expense?'))return;try{await api('/expenses/'+id,{method:'DELETE'});await boot();tourDetail(tid)}catch(e){toast(e.message)}}async function openReceipt(id){try{await receiptModal(id)}catch(e){toast(e.message)}}function mediaCard(p){const canManage=Number(p.owner_member_id)===Number(user.member_id)||(user.role==='admin'&&p.owner_member_id==null);return `<div class="media-card ${p.canReorder?'memory-draggable':''}" data-memory-photo="${p.canReorder?p.id:''}"><img src="/uploads/${encodeURIComponent(p.filename)}" alt="${esc(p.caption||p.album_title||p.title)}" data-lightbox data-src="${esc('/uploads/'+p.filename)}" data-caption="${esc(p.caption||p.album_title||p.title)}">${p.canReorder?'<span class="memory-drag-handle" aria-hidden="true">⠿</span>':''}<div class="media-caption">${p.featured?'★ ':''}${esc(p.caption||p.title||'Memory photo')}${p.location?' · '+esc(p.location):''}<small>${esc(p.album_title||p.title||'Memory')} · ${p.visibility==='private'?'🔒 Private':'Public'}${p.owner_name?' · '+esc(p.owner_name):''}</small></div>${canManage&&p.id?`<div class="media-actions">${p.canReorder?`<button class="btn ghost memory-order-button" data-memory-step="-1" data-photo-id="${p.id}" aria-label="Move earlier">↑</button><button class="btn ghost memory-order-button" data-memory-step="1" data-photo-id="${p.id}" aria-label="Move later">↓</button>`:''}<button class="btn ghost" data-action="editMedia" data-args="[${p.id}]">Edit</button><button class="btn ghost" data-action="deleteMedia" data-args="[${p.id}]">Delete</button></div>`:''}</div>`}
function lightbox(src,caption){modal('Memory photo',esc(caption),`<img class="lightbox-img" src="${esc(src)}" alt="${esc(caption)}">`)}
function editMedia(id){let p=memoryAlbums.flatMap(a=>a.photos.map(x=>({...x,album_title:a.title,owner_member_id:a.owner_member_id}))).find(x=>x.id===id);if(!p)p=data.tours.flatMap(t=>t.gallery).find(x=>x.id===id);if(!p)return;if(p.owner_member_id!==user.member_id&&user.role!=='admin')return;modal('Edit photo details','Update this photo caption and location.',`<form class="form" data-submit="saveMedia" data-id="${id}"><div class="field"><label>Caption</label><input name="caption" value="${esc(p.caption||'')}"></div><div class="field"><label>Location</label><input name="location" value="${esc(p.location||'')}"></div><div class="field"><label>Date</label><input name="taken_at" type="date" value="${p.taken_at?esc(p.taken_at.slice(0,10)):''}"></div><label><input name="featured" type="checkbox" value="1" ${p.featured?'checked':''}> Featured photo</label><button class="btn primary">Save</button></form>`)}
async function saveMedia(e,id){e.preventDefault();try{const f=new FormData(e.target),v=Object.fromEntries(f);await api('/media/'+id,{method:'PUT',body:JSON.stringify(v)});document.querySelector('.overlay')?.remove();if(view==='Memories')await loadMemories();else{await boot();go('Memories')}toast('Photo details saved')}catch(x){toast(x.message)}}
async function deleteMedia(id){if(!confirm('Delete this photo from the album?'))return;try{await api('/media/'+id,{method:'DELETE'});await boot();go('Memories')}catch(x){toast(x.message)}}function settingsPage(){return `<div class="section-head"><div><h2>Group settings</h2><p>Homepage name, message, photos, and contact</p></div></div><div class="card"><form class="form" data-submit="saveSettings"><div class="field"><label>Group name</label><input name="group_name" value="${esc(data.group)}" required></div><div class="field"><label>Hero headline</label><input name="slogan" value="${esc(data.settings.slogan)}"></div><div class="field"><label>Welcome message</label><textarea name="welcome">${esc(data.settings.welcome)}</textarea></div><div class="field"><label>Support Phone / mailto: / https URL</label><input name="support" value="${esc(data.settings.support)}" placeholder="tel:+8801…"></div><div class="field"><label>Group logo — JPG/PNG/WEBP/GIF</label><input name="logo_file" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="field"><label>Homepage hero image — JPG/PNG/WEBP/GIF</label><input name="hero_file" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><button class="btn primary">Settings Save</button></form></div><div class="section-head"><div><h2>SMS notifications</h2><p>Set your Twilio account SID, auth token, and sender number in .env. Provider acceptance means queued, while final delivery depends on the carrier.</p></div></div>`}async function saveSettings(e){e.preventDefault();try{const f=new FormData(e.target),logo=f.get('logo_file'),hero=f.get('hero_file'),v=Object.fromEntries(f);delete v.logo_file;delete v.hero_file;await api('/settings',{method:'PUT',body:JSON.stringify(v)});for(const [asset,img] of [['logo',logo],['hero',hero]])if(img?.size){const fd=new FormData();fd.append('image',img);await api('/settings/'+asset,{method:'POST',body:fd})}await boot();go('Settings');toast('Settings saved')}catch(x){toast(x.message)}}async function logout(){await api('/logout',{method:'POST'});user=null;data=null;boot()}document.addEventListener('click',e=>{const orderButton=e.target.closest('[data-memory-step]');if(orderButton){shiftMemoryPhoto(Number(orderButton.dataset.photoId),Number(orderButton.dataset.memoryStep));return}if(memorySuppressClick&&e.target.closest('[data-memory-photo]')){memorySuppressClick=false;e.preventDefault();return}const album=e.target.closest('[data-memory-album]');if(album){memoryAlbumFilter=album.dataset.memoryAlbum;const filter=document.querySelector('#memoryAlbumFilter');if(filter)filter.value=memoryAlbumFilter;filterMemories();document.querySelectorAll('.memory-album-card').forEach(x=>x.classList.toggle('selected',x.contains(album)));return}const photo=e.target.closest('[data-lightbox]');if(photo){lightbox(photo.dataset.src,photo.dataset.caption);return}const el=e.target.closest('[data-action]');if(!el)return;const name=el.dataset.action,args=JSON.parse(el.dataset.args||'[]');if(name==='closeModal'){el.closest('.overlay')?.remove();return}if(name==='toggleChatWidget'){toggleChatWidget();return}if(name==='newPoll'){newPoll();return}if(name==='newMemoryAlbum'){newMemoryAlbum();return}if(name==='closePoll'){closePoll(...args);return}if(name==='deletePoll'){deletePoll(...args);return}if(name==='setTheme'){setTheme(...args);return}if(name==='selectLocationTour'){window.selectedLocationTour=Number(el.value);render();return}const allowed=new Set(['boot','go','logout','toggleChatWidget','newPoll','closePoll','deletePoll','setTheme','tourDetail','memberDetail','memberForm','tourForm','editTour','editMember','paymentForm','waive','openReceipt','copySms','exportCsv','downloadBackup','expenseForm','deleteExpense','photoForm','editMedia','deleteMedia','editMemoryAlbum','deleteMemoryAlbum','lightbox','filterPayments','deleteAnnouncement','printPage','carouselNext','carouselPrev','carouselSelect','registerScreen','chatPage','sendChatMessage','loginScreen','editOwnProfile','toggleTheme','selectLocationTour','shareLocation','stopLocation']);if(!allowed.has(name))return;const fn=window[name];if(typeof fn==='function')fn(...args)});document.addEventListener('submit',e=>{const f=e.target.closest('[data-submit]');if(!f)return;e.preventDefault();const name=f.dataset.submit,fn=window[name],id=f.dataset.id,ids=[...(id?[id]:[]),...(f.dataset.tour?[f.dataset.tour]:[]),...(f.dataset.member?[f.dataset.member]:[])].map(x=>x===''?null:Number(x));if(typeof fn==='function')fn(e,...ids)});for(const ev of ['input','change'])document.addEventListener(ev,e=>{const filter=e.target.closest('[data-filter]');if(!filter)return;const map={tours:filterTours,members:filterMembers,payments:filterPayments,memories:filterMemories};map[filter.dataset.filter]?.()});document.addEventListener('change',e=>{if(e.target.id==='locationTour'){window.selectedLocationTour=Number(e.target.value);render()}});if(localStorage.getItem('fg-theme-v2')!=='1'){localStorage.setItem('fg-theme','light');localStorage.setItem('fg-theme-v2','1')}const savedTheme=localStorage.getItem('fg-theme')||'light';document.documentElement.dataset.theme=savedTheme;window.addEventListener('beforeunload',()=>{stopLocationWatch();clearInterval(window.chatTimer);clearInterval(window.voiceRecordingTimer);window.activeVoiceRecorder?.stop();window.chatSource?.close();if(window.chatLocationWatch!==undefined)navigator.geolocation.clearWatch(window.chatLocationWatch)});window.addEventListener('afterprint',()=>{});boot();


